var SP_R = {
  r211:{name:'2-1-1 United Way Helpline',tagline:'Free and confidential help finding anything - food, housing, bills, health care. A real person answers, 24 hours a day.',tagline_es:'Ayuda gratuita y confidencial para encontrar cualquier cosa: comida, vivienda, facturas, atención médica. Una persona real contesta. Multilingüe.',tagline_so:'Gargaar bilaash ah, qarsoodi ah si aad u hesho wax kasta: cunto, guri, biilal, daryeel caafimaad. Qof dhabta ahi wuu jawaabaa. Luuqado badan.',tagline_hmn:'Kev pab pub dawb thiab nkag siab nrhiav txhua yam: zaub mov, tsev nyob, nqi lees, kev kho mob. Muaj neeg tiag teb. Ntau hom lus.',phone:'211',addr:'Call or text from anywhere in Minnesota',hrs:'24 hours a day, 7 days a week',url:'https://www.211unitedway.org/',langs:['English','Spanish','Somali','Hmong'],urg:false,d:['all']},
  r988:{name:'988 - Mental Health Crisis Line',tagline:'If you are in a mental health crisis or thinking about hurting yourself, call or text 988. Free. Confidential. Someone answers.',tagline_es:'Si está en una crisis de salud mental o pensando en hacerse daño, llame o envíe un mensaje de texto al 988. Gratis. Confidencial. Alguien contesta.',tagline_so:'Haddaad ku jirto xaalad caafimaad maskax ama aad ka fikirayso in aad nafta waxgarabto, wac ama farriinta qoraalka 988. Bilaash. Qarsoodi. Qof baa jawaabaa.',tagline_hmn:'Yog tias koj muaj teeb meem kev xav lossis xav ua mob rau koj tus kheej, hu lossis xa SMS rau 988. Dawb. Nkag siab. Muaj neeg teb.',phone:'988',addr:'Call or text from anywhere, anytime',hrs:'24 hours a day, 7 days a week',url:'https://988lifeline.org/',langs:['English','Spanish'],urg:true,d:['all']},
  rcra:{name:'Ramsey County Adult Crisis Line',tagline:'For adults in a mental health crisis. Phone support and mobile outreach available. Walk-in clinic open most days.',tagline_es:'Para adultos en crisis de salud mental. Apoyo por teléfono y atención móvil disponible. Clínica de entrada directa abierta la mayoría de los días.',tagline_so:'Dadka waaweyn ee ku jira xaalad caafimaad maskax. Taageero telefoon iyo gargaar socdaal ah. Rugta caafimaadka ayaa furan maalmaha badankooda.',tagline_hmn:'Rau cov neeg laus muaj teeb meem kev xav. Kev pab hauv xov tooj thiab tawm mus pab. Chaw kho mob qhib feem ntau cov hnub.',phone:'651-266-7900',addr:'402 University Ave E, St. Paul (walk-in)',hrs:'Walk-in: Mon-Fri 8am-7pm, Sat-Sun 10am-5pm',url:'https://www.ramseycounty.us/residents/health-medical/clinics-services/mental-health',langs:['English'],urg:true,d:['all']},
  rcrk:{name:'Ramsey County Children Crisis Line',tagline:'For children and teens under 18 in a mental health crisis. Available any time, day or night.',tagline_es:'Para niños y adolescentes menores de 18 años en crisis de salud mental. Disponible en cualquier momento, de día o de noche.',tagline_so:'Carruurta iyo da-yarta ka yar 18 sano ee ku jira xaalad caafimaad maskax. Waa la heli karaa waqti kasta, maalinta iyo habeenka.',tagline_hmn:'Rau cov menyuam thiab cov hluas hnub nyoog qis dua 18 xyoos muaj teeb meem kev xav. Muaj txhua lub sij hawm, nruab hnub lossis hmo ntuj.',phone:'651-266-7878',addr:'Phone and mobile outreach',hrs:'24 hours a day, 7 days a week',url:'https://www.ramseycounty.us/residents/health-medical/clinics-services/mental-health',langs:['English'],urg:true,d:['all']},
  hml:{name:'HOME Line - Free Renter Legal Help',tagline:'Talk to a free housing attorney about your rights as a renter. No appointment needed. Multiple languages available.',tagline_es:'Hable con un abogado de vivienda gratuito sobre sus derechos como inquilino. Sin cita previa. Disponible en múltiples idiomas incluyendo español, somalí y hmong.',tagline_so:'Kula hadal qareen guri bilaash ah oo ku saabsan xuquuqdaada kiro ahaan. Ballan looma baahna. Luuqado badan oo ay ku jirto Soomaali.',tagline_hmn:'Tham nrog kws lij choj tsev nyob dawb txog koj cov cai raws li tus neeg xauj tsev. Tsis tas teem caij. Ntau hom lus suav nrog Hmoob.',phone:'612-728-5767',addr:'Phone - serves all of Minnesota',hrs:'Monday through Friday, business hours',url:'https://homelinemn.org/',langs:['English','Spanish','Somali','Hmong'],urg:false,d:['all']},
  era:{name:'Saint Paul Emergency Rent Help',tagline:'The City may pay up to $3,500 of your late rent directly to your landlord if you have an eviction notice. Applications open the first two days of each month — lottery system. Apply at stpaul.gov/era or call.',tagline_es:'La ciudad puede pagar hasta $3,500 de su renta atrasada directamente a su arrendador si tiene un aviso de desalojo. Las solicitudes abren los primeros dos días de cada mes. Sistema de lotería.',tagline_so:'Magaaladu waxay bixin kartaa ilaa $3,500 kiraadaada daaha ah si toos ah mulkiilaha haddaad haysato ogeysiis masaakinnimo. Codsiyadu waxay furmaan labada maalinta ugu horreysa ee bil walba.',tagline_hmn:'Lub nroog yuav them txog $3,500 ntawm koj nqi xauj tsev ncaj qha rau tus tswv tsev yog tias koj tau txais ntawv ceeb toom. Cov ntawv thov qhib ob hnub xub thawj ntawm txhua hli.',phone:'651-266-6671',addr:'Apply at stpaul.gov/era or by phone',hrs:'Applications open first two days of each month',url:'https://www.stpaul.gov/departments/planning-and-economic-development/housing/emergency-rent-assistance-program-era',langs:['English'],urg:true,d:['all']},
  mla:{name:'Mid-Minnesota Legal Aid',tagline:'Free legal help for people with low income. Housing, family, immigration, and disability cases.',tagline_es:'Ayuda legal gratuita para personas con ingresos bajos. Casos de vivienda, familia, inmigración y discapacidad. Oficinas en las Ciudades Gemelas.',tagline_so:'Gargaar sharci bilaash ah oo loogu talagalay dadka dakhliga hoose. Kiisaska guri, qoys, socdaal iyo naafada.',tagline_hmn:'Kev pab lij choj dawb rau cov neeg muaj nyiaj tau los qis. Cov rooj plaub tsev nyob, tsev neeg, kev tsiv teb tsaws chaw thiab kev xiam oob khab.',phone:'612-334-5970',addr:'Twin Cities offices - phone and in-person',hrs:'Monday through Friday, business hours',url:'https://mylegalaid.org/',langs:['English','Spanish','Somali','Hmong'],urg:false,d:['all']},
  ilcm:{name:'Immigrant Law Center of Minnesota',tagline:'Free immigration legal help for people with low income. Visas, status, naturalization, and deportation defense.',tagline_es:'Ayuda legal de inmigración gratuita para personas con ingresos bajos. Visas, estatus, naturalización y defensa contra la deportación. Sin importar su país de origen.',tagline_so:'Gargaar sharci socdaal bilaash ah oo loogu talagalay dadka dakhliga hoose. Fiisas, xaalad, dawladnimada iyo difaaca saridda. Waxba kama tirsana dalkaad ka timid.',tagline_hmn:'Kev pab lij choj kev tsiv teb tsaws chaw dawb rau cov neeg muaj nyiaj tau los qis. Vis xas, xwm txheej, pej xeem thiab kev tiv thaiv raug ntiab tawm.',phone:'1-800-223-1368',addr:'St. Paul and Twin Cities offices',hrs:'ICE detainees: Mon-Thu 1-3pm. All others: call.',url:'https://www.ilcm.org/',langs:['English','Spanish','Somali','Hmong'],urg:false,d:['all']},
  spimm:{name:'Saint Paul Immigration Resources',tagline:'Official City of Saint Paul page. Know-your-rights information, emergency contacts, and legal help. Updated regularly.',tagline_es:'Página oficial de la Ciudad de Saint Paul con información sobre sus derechos de inmigración, contactos de emergencia y recursos legales. Actualizada regularmente.',tagline_so:'Bogga rasmiga ah ee Magaalada Saint Paul oo leh macluumaadka xuquuqda socdaalka, xiriirinta xaalada degdegga ah iyo kheyraadka sharciga. Si joogto ah ayaa la cusbooneysiiyaa.',tagline_hmn:'Nplooj ntawv rasmim ntawm Nroog Saint Paul txog koj cov cai kev tsiv teb tsaws chaw, cov xov tooj xwm txheej ceev thiab cov chaw pab lij choj.',phone:null,addr:'stpaul.gov/immigration-resources',hrs:'Online 24 hours a day',url:'https://www.stpaul.gov/departments/city-attorney/immigration-resources',langs:['English','Spanish','Somali','Hmong','Karen'],urg:true,d:['all']},
  cap:{name:'Help Paying Energy Bills (CAP)',tagline:'Free help paying your heating and energy bills through the LIHEAP program for qualifying households in Ramsey County.',tagline_es:'Ayuda gratuita para pagar sus facturas de calefacción y energía a través del programa LIHEAP para hogares elegibles en el Condado de Ramsey.',tagline_so:'Gargaar bilaash ah si loo bixiyo biilasha kulaylka iyo tamarta adiga oo adeegsanaya barnaamijka LIHEAP ee guryaha xaqiiqda leh ee Degmada Ramsey.',tagline_hmn:'Kev pab dawb them koj cov nqi kub thiab hluav taws xob los ntawm txoj hauj lwm LIHEAP rau cov tsev neeg tsim nyog hauv Ramsey County.',phone:'651-645-6470',addr:'450 Syndicate St N Suite 122, St. Paul 55104',hrs:'Monday through Friday, 8am-4:30pm',url:'https://caprw.org/',langs:['English'],urg:false,d:['all']},
  mnc:{name:'Minnesota Community Care',tagline:'Health care for everyone regardless of income or insurance. Sliding scale pricing. Multiple Saint Paul locations. No one is turned away.',tagline_es:'Atención médica para todos sin importar su ingreso o seguro. Precio según ingresos. Múltiples ubicaciones en Saint Paul. Nadie es rechazado.',tagline_so:'Daryeel caafimaad oo loogu talagalay dhammaan dadka dakhliga ama caymiska aan la eegin. Qiimaha waxaa lagu xisaabiyaa dakhliga. Nadie looma diidin.',tagline_hmn:'Kev kho mob rau txhua tus neeg tsis quav ntsej nyiaj tau los lossis kev pov hwm. Nqi raws li nyiaj tau los. Ntau qhov chaw hauv Saint Paul. Tsis muaj leej twg raug tsis lees txais.',phone:'651-778-2884',addr:'Multiple locations across Saint Paul - call for nearest',hrs:'Monday through Friday, 8am-4pm',url:'https://www.mncare.org/',langs:['English','Spanish','Somali','Hmong'],urg:false,d:['all']},
  wlk:{name:'Walk-In Counseling Center',tagline:'Free anonymous counseling. No appointment, no insurance, no ID needed. Come in during clinic hours.',tagline_es:'Consejería anónima gratuita. Sin cita previa, sin seguro, sin identificación. Venga durante el horario de la clínica.',tagline_so:'La tashanaan qarsoodi bilaash ah. Ballan, caymis, aqoonsiyo looma baahna. Waqtiga rugta caafimaadka iman.',tagline_hmn:'Kev tham dawb tsis qhia leej twg. Tsis tas teem caij, tsis tas muaj kev pov hwm, tsis tas muaj ntawv pov thawj.',phone:'612-870-0565',addr:'Minneapolis and St. Paul locations',hrs:'Weekdays during clinic hours',url:'https://walkin.org/',langs:['English'],urg:false,d:['all']},
  wilder:{name:'Wilder Foundation - Mental Health',tagline:'Outpatient mental health and addiction counseling for all ages. Sliding scale. Walk-in Mon-Fri. Hmong and Karen services available.',tagline_es:'Consejería ambulatoria de salud mental y adicciones para todas las edades. Precio según ingresos. Entrada directa lunes a viernes. Servicios en hmong y karen disponibles.',tagline_so:'La tashanaan caafimaad maskax iyo ku tiirsanaanshaha dadka waaweyn iyo carruurta. Qiimaha waxaa lagu xisaabiyaa dakhliga. Geli toos Isniin-Jimce. Adeegyada Hmong iyo Karen.',tagline_hmn:'Kev tham kev xav thiab kev haus dej haus cawv rau txhua hnub nyoog. Nqi raws li nyiaj tau los. Mus nkag ncaj qha Hnub Monday-Friday. Muaj kev pab lus Hmoob.',phone:'651-280-2310',addr:'451 Lexington Pkwy N, St. Paul 55104',hrs:'Walk-in Mon-Thu 9am-3pm, Fri 9am-1pm; appointments available',url:'https://www.wilder.org/services/mental-health-services/',langs:['English','Hmong','Karen'],urg:false,d:['all']},
  rcc:{name:'Ramsey County Child Care Help',tagline:'Help paying for child care if you work, go to school, or are in job training.',tagline_es:'Ayuda para pagar el cuidado infantil si trabaja, estudia o está en capacitación laboral. Solicite en línea o por teléfono.',tagline_so:'Caawimo loogu talagalay lacag bixinta daryeelka carruurnimada haddaad shaqeyso, waxbaraneyso ama tababarno shaqo.',tagline_hmn:'Kev pab them nqi tu menyuam yog tias koj ua hauj lwm, kawm ntawv, lossis kawm txuj ci hauj lwm.',phone:'651-266-4444',addr:'Apply online or by phone',hrs:'Monday through Friday, 8am-4:30pm',url:'https://www.ramseycounty.us/residents/children-family-services/child-care-assistance',langs:['English','Spanish','Somali','Hmong'],urg:false,d:['all']},
  iimn:{name:'International Institute of Minnesota',tagline:'Refugee resettlement, citizenship help, English classes, and job training for immigrants and refugees.',tagline_es:'Reasentamiento de refugiados, ayuda con ciudadanía, clases de inglés y capacitación laboral para inmigrantes y refugiados en Saint Paul.',tagline_so:'Dejinta qaxootiga, gargaar dawladnimada, fasallada Ingiriisiga iyo tababarka shaqada oo loogu talagalay socdaalayaasha iyo qaxootiga Saint Paul.',tagline_hmn:'Kev rov txias rau cov neeg tawg rog, kev pab pej xeem, cov chav kawm lus Askiv thiab kev kawm txuj ci hauj lwm rau cov neeg tsiv teb tsaws chaw hauv Saint Paul.',phone:'651-647-0191',addr:'1694 Como Ave, St. Paul 55108',hrs:'Monday through Friday, business hours',url:'https://iimn.org/',langs:['English','Spanish','Somali','Hmong','Karen'],urg:false,d:['all']},
  wom_adv:{name:"Women's Advocates - Domestic Violence",tagline:'Safe shelter and support for women and children escaping domestic violence. Free, confidential, 24-hour crisis line.',tagline_es:'Refugio seguro y apoyo para mujeres y niños que escapan de la violencia doméstica. Línea de crisis gratuita y confidencial disponible las 24 horas. Ubicación confidencial en Saint Paul.',tagline_so:'Magangal ammaan ah iyo taageero oo loogu talagalay haweenka iyo carruurta ka cararaysa rabshadda guriga. Khadka xaalada degdegga bilaashka ah ee qarsoodi ah ee 24-saacadood.',tagline_hmn:'Chaw pw nyab xeeb thiab kev pab txhawb rau cov pojniam thiab menyuam tawg ntawm kev tsim txom hauv tsev. Kav xov tooj dawb, nkag siab, 24 teev. Qhov chaw nkag siab hauv Saint Paul.',phone:'651-227-8284',addr:'St. Paul (confidential location)',hrs:'24 hours a day, 7 days a week',url:'https://wadvocates.org/',langs:['English'],urg:true,d:['all']},
  cornerstone:{name:'Cornerstone - Crisis Line',tagline:'Crisis help for anyone experiencing domestic violence, sexual violence, or human trafficking. Confidential, 24 hours.',tagline_es:'Ayuda en crisis para cualquier persona que experimente violencia doméstica, violencia sexual o tráfico. Confidencial, 24 horas. Sin importar su estatus migratorio.',tagline_so:'Gargaar xaalad degdeg ah oo loogu talagalay cidda kula kulmaysa rabshadda guriga, rabshadda galmoodka ama ganacsiga aadanaha. Qarsoodi, 24 saacadood.',tagline_hmn:'Kev pab xwm txheej ceev rau txhua tus neeg raug kev tsim txom hauv tsev, kev tsim txom poj niam txiv neej, lossis kev muag neeg. Nkag siab, 24 teev.',phone:'1-866-223-1111',addr:'Call 1-866-223-1111 or text 612-399-9995. Statewide 24/7 crisis line (Day One). Advocate appointments: 952-884-0330.',hrs:'24 hours a day, 7 days a week',url:'https://cornerstonemn.org/',langs:['English'],urg:true,d:['all']},
  rshlt:{name:'Ramsey County Shelter Help',tagline:'The single point of contact for emergency shelter in Ramsey County. For single adults or families with nowhere to stay tonight.',tagline_es:'El punto de contacto único para refugio de emergencia en el Condado de Ramsey. Para adultos solos o familias sin donde quedarse esta noche. Llame primero.',tagline_so:'Xarunta keliya ee xiriirka xaalada degdegga ah ee magangalka ee Degmada Ramsey. Dadka waaweyn keliya ama qoysaska aan guri haysan habeenkan.',tagline_hmn:'Qhov chaw sib cuag ib lub xwb rau kev zov chaw pw xwm txheej ceev hauv Ramsey County. Rau cov neeg laus ib leeg lossis cov tsev neeg tsis muaj qhov nyob hmo no.',phone:'651-266-1050',addr:'Call first - they coordinate shelter placement',hrs:'24 hours a day, 7 days a week',url:'https://www.ramseycounty.us/',langs:['English'],urg:true,d:['all']},
  mfhl:{name:'Minnesota Food HelpLine',tagline:'Free statewide helpline to find food shelves, get SNAP benefits, and find food programs near you. Call or text. Multilingual.',tagline_es:'Línea de ayuda gratuita en todo el estado para encontrar despensas de alimentos, obtener beneficios SNAP y localizar programas de alimentos cerca de usted. Llame o envíe un mensaje de texto. Multilingüe.',tagline_so:'Khadka gargaarka bilaashka ee gobolka si aad u hesho raafadaha cuntada, u hesho faa\'iidooyinka SNAP oo u hesho barnaamijyada cuntada ee kuu dhow. Luuqado badan.',tagline_hmn:'Kav xov tooj pab dawb thoob plaws lub xeev nrhiav cov chaw muab khoom noj dawb, tau txais cov txiaj ntsig SNAP thiab nrhiav cov hauj lwm zaub mov ze koj.',phone:'1-888-711-1151',addr:'Call or text from anywhere in Minnesota',hrs:'Monday through Friday, 10am-5pm',url:'https://www.hungersolutions.org/programs/mn-food-helpline/',langs:['English','Spanish','Hmong','Somali'],urg:false,d:['all']},
  safezone:{name:'SafeZone - Youth Housing',tagline:'Housing and support services for young people ages 14-24 who are homeless or at risk. Hot meals, showers, clothing, case management, mental health, and housing help. No ID required.',tagline_es:'Vivienda y servicios de apoyo para jóvenes de 14 a 24 años sin hogar o en riesgo. Comidas calientes, duchas, ropa, manejo de casos, salud mental y ayuda de vivienda. No se requiere identificación.',tagline_so:'Guri iyo adeegyada taageerada loogu talagalay da-yarta 14-24 jirka ah ee aanay lahayn meel ku noolaadaan ama halis ku jira. Cuntada kulul, musqusha, dharka. Aqoonsiyo looma baahna.',tagline_hmn:'Tsev nyob thiab kev pab txhawb rau cov hluas hnub nyoog 14-24 xyoos tsis muaj tsev lossis muaj kev pheej hmoo. Zaub mov kub, dej ntxuav cev, ris tsho. Tsis tas muaj ntawv pov thawj.',phone:'651-224-9644',addr:'130 E 7th St, St. Paul 55101',hrs:'Monday through Friday, 9am-6pm',url:'https://face2face.org/housing',langs:['English'],urg:true,d:['all']},
  wicprog:{name:'WIC - Food Help for Families',tagline:'Free food benefits for pregnant women, new moms, babies, and children under 5. Also nutrition education and referrals.',tagline_es:'Beneficios de alimentos gratuitos para mujeres embarazadas, nuevas mamás, bebés y niños menores de 5 años. También educación nutricional y referencias a otros servicios.',tagline_so:'Faa\'iidooyinka cuntada bilaashka ah oo loogu talagalay haweenka uurka leh, hooyadaha cusub, ilmaha yar yar iyo carruurta ka yar 5 sano. Waxbarashada nafaqada iyo tixraacyada sidoo kale.',tagline_hmn:'Cov txiaj ntsig khoom noj dawb rau cov pojniam xeeb tub, cov niam tshiab, cov menyuam yaus thiab cov menyuam hnub nyoog qis dua 5 xyoos. Kev qhia zaub mov thiab kev xa mus lwm qhov.',phone:'651-266-1300',addr:'Multiple Saint Paul locations',hrs:'Monday-Thursday 8am-6:30pm, Friday 9:30am-3pm',url:'https://www.health.state.mn.us/people/wic/',langs:['English','Spanish','Hmong','Somali'],urg:false,d:['all']},
  mrf:{name:'Merrick Community Services Food Shelf',tagline:'You choose what your family needs - like shopping at a store. Client choice model. East Side and Maplewood residents.',tagline_es:'Usted elige lo que su familia necesita, como hacer compras en una tienda. Modelo de elección del cliente. Residentes del East Side y Maplewood.',tagline_so:'Adiga oo dooraneyso waxa qoyskaagu u baahan yahay, sida xafiisyada badeecadaha. Qaabka doorashada macmiilka. Deganaayaasha East Side iyo Maplewood.',tagline_hmn:'Koj xaiv yam uas koj tsev neeg xav tau, zoo li mus yuav khoom tom khw. Tus qauv xaiv ntawm tus neeg siv. Cov neeg nyob East Side thiab Maplewood.',phone:'651-287-2088',addr:'1669 Arcade St N, St. Paul 55106',hrs:'Drive-thru Door 2A: Mon 3-5pm, Tue 10am-noon. In-person Door 3: Wed & Thu 10am-noon',url:'https://merrickcs.org/community-services/food/',langs:['English'],urg:false,d:['east']},
  fotv:{name:'Fruit of the Vine Food Shelf',tagline:'Welcoming food shelf at First Covenant Church on Arcade Street. Client choice. Spanish support available.',tagline_es:'Despensa de alimentos acogedora en la Primera Iglesia del Pacto en Arcade Street. Modelo de elección del cliente. Apoyo en español disponible.',tagline_so:'Raafadda cuntada ee soo dhaweyneysa ee Kaniisadda Heshiiska Kowaad ee Arcade Street. Qaabka doorashada macmiilka. Taageero Isbaanish ah ayaa diyaar ah.',tagline_hmn:'Chaw muab khoom noj zoo siab txais tos ntawm First Covenant Church ntawm Arcade Street. Tus neeg siv xaiv. Kev pab lus Spanish muaj.',phone:'952-595-5980',addr:'1280 Arcade St, St. Paul 55106',hrs:'Tue 3-6pm, Fri 11am-1pm, Sat 9am-noon',url:'https://vcsmn.org/services/',langs:['English','Spanish'],urg:false,d:['east']},
  nbhf:{name:'Neighborhood House Food Market',tagline:'Free monthly food market. No ID or papers needed. Open to everyone. Multiple Saint Paul locations.',tagline_es:'Mercado de alimentos gratuito mensual. No se necesita identificación ni documentos. Abierto a todos los residentes del área de Saint Paul.',tagline_so:'Suuq cunto bilaash ah oo bilo. Aqoonsiyo ama warqado looma baahna. Furan dadka oo dhan ee Saint Paul.',tagline_hmn:'Khw khoom noj dawb txhua hli. Tsis tas muaj ntawv pov thawj lossis cov ntawv. Qhib rau txhua tus neeg nyob hauv Saint Paul.',phone:'651-789-3630',addr:'Multiple Saint Paul locations - call for schedule',hrs:'Monthly - call for dates and locations',url:'https://neighborhoodhousemn.org/programs/food-support/',langs:['English','Hmong','Spanish','Somali'],urg:false,d:['east','west','high']},
  salv_east:{name:'Salvation Army - East Side Food Shelf',tagline:'Food shelf and free hot meals. Culturally specific foods available. East Side residents.',tagline_es:'Despensa de alimentos y comidas calientes gratuitas. Alimentos culturalmente específicos disponibles. Para residentes del East Side.',tagline_so:'Raafadda cuntada iyo cuntada kulul ee bilaashka ah. Cuntada gaar ah ee dhaqanka ayaa diyaar ah. Deganaayaasha East Side.',tagline_hmn:'Chaw muab khoom noj thiab zaub mov kub dawb. Muaj cov khoom noj tsim nyog rau txoj kab lis kev cai. Rau cov neeg nyob East Side.',phone:'651-776-8169',addr:'1019 Payne Ave, St. Paul 55130',hrs:'Food shelf: Tue & Thu 9-11am and 1-3pm; Fri 10:30-11:30am. Meals: Mon/Tue/Thu/Fri 11:45am-12:45pm',url:'https://centralusa.salvationarmy.org/twin-cities/get-food-help',langs:['English'],urg:false,d:['east']},
  clues:{name:'CLUES - Health, Legal, and Job Help',tagline:'Walk in for mental health care, legal help, financial coaching, and job support. Any insurance or none.',tagline_es:'Entre directamente para atención de salud mental, ayuda legal, asesoría financiera y apoyo laboral en el East Side. Con cualquier seguro o sin seguro.',tagline_so:'Geli si toos ah daryeelka caafimaadka maskaxda, gargaarka sharciga, talaabada maaliyadda iyo taageero shaqo East Side. Caymis kasta ama waxba.',tagline_hmn:'Mus nkag ncaj qha rau kev kho mob kev xav, kev pab lij choj, kev qhia txog nyiaj thiab kev txhawb hauj lwm ntawm East Side. Kev pov hwm twg los tau lossis tsis muaj.',phone:'651-379-4200',addr:'797 E 7th St, St. Paul 55106',hrs:'Call for hours',url:'https://clues.org/',langs:['English','Spanish'],urg:false,d:['east','west']},
  icm:{name:'Immigrant Connection Mosaic',tagline:'Low-cost immigration legal help on the East Side. Naturalization, visas, status renewals. Approved by U.S. Dept of Justice.',tagline_es:'Ayuda legal de inmigración de bajo costo en el East Side de Saint Paul. Naturalización, visas, renovaciones de estatus. Aprobado por el Departamento de Justicia de EE.UU.',tagline_so:'Gargaar sharci socdaal qiimaha hoose ah ee East Side Saint Paul. Dawladnimada, fiisasaha, cusbooneysiinta xaaladda. Wasiirrada Caddaaladda ee Mareykanka ayaa ansixiyay.',tagline_hmn:'Kev pab lij choj kev tsiv teb tsaws chaw nqi qis ntawm East Side Saint Paul. Pej xeem, vis xas, kev hloov xwm txheej. Tau txais kev pom zoo ntawm Tus Kaws Lij Choj Tsoomfwv.',phone:'651-583-8797',addr:'East Wheelock Pkwy near Payne Ave, St. Paul',hrs:'By appointment',url:'https://www.mosaicstpaul.org/learn-more',langs:['English'],urg:false,d:['east']},
  mrj:{name:'Merrick - Job and Employment Help',tagline:'Free help with job searching and resumes on the East Side.',tagline_es:'Ayuda gratuita para búsqueda de empleo y currículos en el East Side de Saint Paul. Sin cita previa.',tagline_so:'Gargaar bilaash ah oo ku saabsan raadinta shaqada iyo seeraha ee East Side Saint Paul.',tagline_hmn:'Kev pab dawb nrhiav hauj lwm thiab sau ntawv thov hauj lwm ntawm East Side Saint Paul.',phone:'651-771-9339',addr:'1669 Arcade St N, St. Paul 55106',hrs:'Monday through Thursday, 8am-5:30pm',url:'https://merrickcs.org/',langs:['English'],urg:false,d:['east']},
  f2f:{name:'Face to Face - Youth Support',tagline:'Drop-in shelter and mental health support for young people ages 14 to 24. No appointment needed.',tagline_es:'Refugio de entrada directa y apoyo de salud mental para jóvenes de 14 a 24 años en crisis. Sin cita previa. East Side de Saint Paul.',tagline_so:'Magangal la geli karo si toos ah iyo taageero caafimaadka maskaxda oo loogu talagalay da-yarta 14-24 jirka ah ee xaalad ku jira. Ballan looma baahna.',tagline_hmn:'Chaw pw mus nkag ncaj qha thiab kev pab kev xav rau cov hluas hnub nyoog 14-24 xyoos muaj teeb meem. Tsis tas teem caij.',phone:'651-772-5555',addr:'1165 Arcade St, St. Paul 55106',hrs:'Mon-Thu 10am-6pm, Fri 10am-4pm',url:'https://face2face.org/',langs:['English','Hmong'],urg:false,d:['east']},
  ugm:{name:'Union Gospel Mission - Meals and Shelter',tagline:'Free meals three times daily, 365 days a year. Emergency shelter intake 24 hours. Men, women, and children.',tagline_es:'Comidas gratuitas tres veces al día, 365 días al año. Admisión a refugio de emergencia disponible. Abierto a hombres, mujeres y niños sin distinción.',tagline_so:'Cuntada bilaashka ah saddex jeer maalintii, 365 maalin sannadkii. Qabsashada magangalka xaalada degdegga ah. Ragga, haweenka iyo carruurta oo dhan.',tagline_hmn:'Zaub mov dawb peb zaug ib hnub, 365 hnub ib xyoos. Chaw pw xwm txheej ceev. Txiv neej, pojniam thiab menyuam txhua tus.',phone:'651-228-1800',addr:'435 University Ave E, St. Paul 55130',hrs:'Meals: 6:30-7:30am, 12-1pm, 5:30-6:30pm. Shelter: 24/7',url:'https://www.ugmtc.org/',langs:['English'],urg:true,d:['east','down']},
  nca:{name:'NCA - East Side Food Shelf',tagline:'Neighborhood food shelf serving the East Side. Call for an appointment.',tagline_es:'Despensa de alimentos del vecindario que sirve al East Side de Saint Paul. Llame para hacer una cita.',tagline_so:'Raafadda cuntada ee xaafadda ee u adeegeysa East Side Saint Paul. Wac ballanka.',tagline_hmn:'Chaw muab khoom noj hauv zos ua rau East Side Saint Paul. Hu rau teem caij.',phone:'651-243-1399',addr:'539 Phalen Blvd, St. Paul 55130',hrs:'By appointment - call first',url:'https://www.nca-mn.org/',langs:['English'],urg:false,d:['east']},
  ms_pantry:{name:'Metro State University Food Pantry',tagline:'Free food pantry open to everyone in the community, not just students. Walk in during open hours.',tagline_es:'Despensa de alimentos gratuita abierta a todos en la comunidad, no solo a estudiantes. Entre durante el horario de apertura sin cita.',tagline_so:'Raafadda cuntada bilaashka ah ee furan dadka oo dhan ee bulshada, kaliya arday maaha. Geli inta lagu jiro saacadaha furan.',tagline_hmn:'Chaw muab khoom noj dawb qhib rau txhua tus hauv zej zog, tsis yog cov tub ntxhais kawm ntawv xwb. Mus nkag thaum lub sij hawm qhib.',phone:'651-793-1571',addr:'700 E 7th St, St. Paul 55106',hrs:'Call for current hours',url:'https://www.metrostate.edu/students/support/food-pantry',langs:['English'],urg:false,d:['east']},
  mncw:{name:'Minnesota Community Care - West Side',tagline:'Health care for everyone. Founded in 1969 to serve the West Side community. Sliding scale. No one turned away.',tagline_es:'Atención médica para todos. Fundada en 1969 para servir a la comunidad del West Side. Precio según ingresos. Nadie es rechazado.',tagline_so:'Daryeel caafimaad oo loogu talagalay dhammaan dadka. 1969 waxaa loogu aasaasay inay u adeegto bulshada West Side. Qiimaha waxaa lagu xisaabiyaa dakhliga.',tagline_hmn:'Kev kho mob rau txhua tus. Tsim nyem xyoo 1969 los pab zej zog West Side. Nqi raws li nyiaj tau los. Tsis muaj leej twg raug tsis lees txais.',phone:'651-312-1996',addr:'30 E Baker St, St. Paul 55107',hrs:'Monday through Friday, 8am-4pm',url:'https://www.mncare.org/',langs:['English','Spanish'],urg:false,d:['west']},
  wsco:{name:'West Side Community Organization',tagline:'Your neighborhood organization. Tenant rights, housing help, and connecting to resources on the West Side.',tagline_es:'Su organización vecinal en el West Side. Derechos de inquilinos, ayuda de vivienda y conexión a recursos comunitarios.',tagline_so:'Hay\'adda xaafaddaada ee West Side. Xuquuqda kiraystayaasha, gargaarka guriga iyo xiriirka kheyraadka bulshada.',tagline_hmn:'Koj lub koom haum hauv zos ntawm West Side. Cov cai tus neeg xauj tsev, kev pab tsev nyob thiab kev sib txuas rau cov chaw pab hauv zej zog.',phone:'651-293-1708',addr:'West Side, St. Paul',hrs:'Call for hours',url:'https://www.wsco.org/',langs:['English','Spanish'],urg:false,d:['west']},
  salv_cit:{name:'Salvation Army Citadel - Food Shelf',tagline:'Food shelf for ZIP codes 55102-55105, 55116, 55117. Free produce distribution Fridays. Senior brown bag first Thursday monthly.',tagline_es:'Despensa de alimentos para códigos postales 55102-55105, 55116, 55117. Distribución gratuita de productos los viernes. Bolsa mensual especial para personas mayores el primer jueves.',tagline_so:'Raafadda cuntada ee koodka boostada 55102-55105, 55116, 55117. Qaybinta khudradda bilaashka ah ee Jimcaha. Kiis gaar ah oo loogu talagalay waayeelka Khamiskii ugu horreysa ee bilaha.',tagline_hmn:'Chaw muab khoom noj rau cov zip code 55102-55105, 55116, 55117. Muab khoom qoob loo dawb hnub Friday. Hnab tshwj xeeb rau cov laus hnub Thursday thib ib ntawm txhua hli.',phone:'651-224-4316',addr:'401 West 7th St, St. Paul 55102',hrs:'Mon & Wed 10am-12pm. Produce: Fri 11am-3pm',url:'https://centralusa.salvationarmy.org/twin-cities/get-food-help',langs:['English'],urg:false,d:['west','down']},
  nbhh:{name:'Neighborhood House - West Side',tagline:'Family support, food, youth programs, and housing help on the West Side.',tagline_es:'Apoyo familiar, alimentos, programas juveniles y ayuda de vivienda en el West Side de Saint Paul.',tagline_so:'Taageero qoys, cunto, barnaamijyada da-yarta iyo gargaarka guriga ee West Side Saint Paul.',tagline_hmn:'Kev pab tsev neeg, zaub mov, cov hauj lwm rau cov hluas thiab kev pab tsev nyob ntawm West Side Saint Paul.',phone:'651-789-3602',addr:'179 Robie St E, St. Paul 55107',hrs:'Call Service Connect number for current hours',url:'https://neighborhoodhousemn.org/',langs:['English','Spanish','Hmong','Somali'],urg:false,d:['west']},
  st_matt:{name:"St. Matthew's Church - Free Dinners",tagline:'Free dinner served Monday through Friday for everyone. No ID or papers required.',tagline_es:'Cena gratuita servida de lunes a viernes para todos. No se requiere identificación ni documentos.',tagline_so:'Casho bilaash ah oo la gurmaa Isniin ilaa Jimce dadka oo dhan. Aqoonsiyo ama warqado looma baahna.',tagline_hmn:'Zaub mov hmo dawb muab hnub Monday txog Friday rau txhua tus. Tsis tas muaj ntawv pov thawj lossis cov ntawv.',phone:'651-224-9793',addr:'510 Hall Ave, St. Paul 55107',hrs:'Monday through Friday, 5-6pm (closed major holidays; Lent: Mon-Thu only)',url:null,langs:['English'],urg:false,d:['west']},
  clues_w:{name:'CLUES - West Side Services',tagline:'Mental health, legal help, job training, and financial coaching. Founded on the West Side. All are welcome.',tagline_es:'Salud mental, ayuda legal, capacitación laboral y asesoría financiera. Fundada en el West Side de Saint Paul. Todos son bienvenidos.',tagline_so:'Caafimaadka maskaxda, gargaarka sharciga, tababarka shaqada iyo talaabada maaliyadda. West Side Saint Paul waxaa loogu aasaasay. Dhammaan waa soo dhaweyn.',tagline_hmn:'Kev pab kev xav, kev pab lij choj, kev kawm txuj ci hauj lwm thiab kev qhia txog nyiaj. Tsim nyem ntawm West Side Saint Paul. Txhua tus tau txais tos.',phone:'651-379-4240',addr:'West Side, St. Paul',hrs:'Call for appointments',url:'https://clues.org/',langs:['English','Spanish'],urg:false,d:['west']},
  ftft:{name:'Feeding Frogtown',tagline:'Free groceries every other Friday. You pick what you need. No ID. No appointment. No paperwork. Open to everyone.',tagline_es:'Comestibles gratuitos cada dos viernes. Usted elige lo que necesita. No se requiere identificación, cita ni papeleo. Abierto a todos.',tagline_so:'Raasinta bilaashka ah sabtida kasta labaad. Adiga oo dooraneyso waxa aad u baahan tahay. Aqoonsiyo, ballan ama warqado looma baahna. Furan dadka oo dhan.',tagline_hmn:'Khoom noj dawb txhua ob lub hnub Friday. Koj xaiv yam koj xav tau. Tsis tas muaj ntawv pov thawj, teem caij, lossis ntaub ntawv. Qhib rau txhua tus.',phone:'651-236-8699',addr:'685 Minnehaha Ave W (West Minnehaha Recreation Center), St. Paul',hrs:'Every other Friday, 3pm-6pm',url:'https://www.frogtownmn.org/feedingfrogtown',langs:['English','Hmong','Karen'],urg:false,d:['frog']},
  fna:{name:'Frogtown Neighborhood Association',tagline:'Your neighborhood organization. Tenant rights, housing help, and resources for Frogtown residents.',tagline_es:'Su organización vecinal en Frogtown. Derechos de inquilinos, ayuda de vivienda y recursos para residentes de Frogtown y Thomas-Dale.',tagline_so:'Hay\'adda xaafaddaada ee Frogtown. Xuquuqda kiraystayaasha, gargaarka guriga iyo kheyraadka deganaayaasha Frogtown.',tagline_hmn:'Koj lub koom haum hauv zos hauv Frogtown. Cov cai tus neeg xauj tsev, kev pab tsev nyob thiab cov chaw pab rau cov neeg nyob Frogtown.',phone:'651-236-8699',addr:'501 Dale St N, St. Paul 55103',hrs:'Call for hours',url:'https://www.frogtownmn.org/',langs:['English','Hmong','Karen'],urg:false,d:['frog']},
  mncf:{name:'Minnesota Community Care - Frogtown',tagline:'Health care for everyone. Youth clinic for ages 12 to 22 on University Ave. Sliding scale. No one turned away.',tagline_es:'Atención médica para todos en Frogtown. Clínica juvenil para jóvenes de 12 a 22 años en University Avenue. Precio según ingresos. Nadie es rechazado.',tagline_so:'Daryeel caafimaad oo loogu talagalay dhammaan dadka Frogtown. Rugta caafimaadka ee da-yarta 12-22 jirka ee University Ave. Qiimaha waxaa lagu xisaabiyaa dakhliga.',tagline_hmn:'Kev kho mob rau txhua tus hauv Frogtown. Chaw kho mob rau cov hluas hnub nyoog 12-22 xyoos ntawm University Ave. Nqi raws li nyiaj tau los.',phone:'651-793-2234',addr:'1212 University Ave, St. Paul 55104',hrs:'Monday through Thursday, 8am-4pm',url:'https://www.mncare.org/',langs:['English','Spanish','Hmong','Somali'],urg:false,d:['frog','midway']},
  focus:{name:'FOCUS - Food Shelf on Rice Street',tagline:'Food shelf serving North End and Frogtown. No zip code restrictions.',tagline_es:'Despensa de alimentos para el North End y Frogtown de Saint Paul. Sin restricciones de código postal. Entre durante el horario de apertura.',tagline_so:'Raafadda cuntada ee u adeegeysa North End iyo Frogtown Saint Paul. Xaddidaada koodka boostada ma jirto.',tagline_hmn:'Chaw muab khoom noj ua rau North End thiab Frogtown Saint Paul. Tsis muaj kev txwv zip code.',phone:'651-222-0712',addr:'550 Rice St, St. Paul 55103',hrs:'Call for current hours',url:'https://www.focusmn.org/programs',langs:['English'],urg:false,d:['frog','north']},
  hallie:{name:'Hallie Q. Brown Food Shelf',tagline:'Serving the Rondo community since 1929. By appointment only. You choose what your family needs. Fresh produce and food delivery available.',tagline_es:'Sirviendo a la comunidad de Rondo desde 1929. Solo con cita. Usted elige lo que su familia necesita. Productos frescos y entrega de alimentos disponibles.',tagline_so:'U adeegeysa bulshada Rondo tan iyo 1929. Ballan oo keliya. Adiga oo dooraneyso waxa qoyskaagu u baahan yahay. Khudradda cusub iyo gaadhsiinta cuntada ayaa diyaar ah.',tagline_hmn:'Pab cuag zej zog Rondo txij xyoo 1929. Teem caij xwb. Koj xaiv yam koj tsev neeg xav tau. Muaj khoom qoob loo tshiab thiab kev xa zaub mov.',phone:'651-224-4606',addr:'270 North Kent, St. Paul 55102',hrs:'By appointment Mon-Fri 9am-5pm - call first',url:'https://www.hallieqbrown.org/',langs:['English'],urg:false,d:['rondo']},
  hallie_ctr:{name:'Hallie Q. Brown Community Center',tagline:'Community hub for Rondo since 1929. Youth programs, senior services, and community support. Library services temporarily here too.',tagline_es:'Centro comunitario para la comunidad de Rondo desde 1929. Programas juveniles, servicios para personas mayores y apoyo comunitario en Summit-University.',tagline_so:'Xarunta bulshada ee Rondo tan iyo 1929. Barnaamijyada da-yarta, adeegyada waayeelka iyo taageero bulshada ee Summit-University.',tagline_hmn:'Lub hauv paus zej zog rau Rondo txij xyoo 1929. Cov hauj lwm rau cov hluas, kev pab cov laus thiab kev txhawb zej zog ntawm Summit-University.',phone:'651-224-4601',addr:'270 Kent St, St. Paul 55102',hrs:'Monday through Friday, 9am-5pm',url:'https://www.hallieqbrown.org/',langs:['English'],urg:false,d:['rondo']},
  aurora:{name:'Aurora St. Anthony - Housing Help',tagline:'Helps people in Rondo, Frogtown, and Summit-University find and keep affordable housing.',tagline_es:'Ayuda a personas en Rondo, Frogtown y Summit-University a encontrar y mantener vivienda asequible. Asesoría de vivienda gratuita.',tagline_so:'Caawimayaa dadka Rondo, Frogtown iyo Summit-University si ay u helaan oo ay u hayaan guri fudud. Talo guri bilaash ah.',tagline_hmn:'Pab cov neeg hauv Rondo, Frogtown thiab Summit-University nrhiav thiab khaws tsev nyob muaj nqi pheej yig.',phone:'651-221-0512',addr:'Rondo and Frogtown area, St. Paul',hrs:'Call for hours',url:'https://www.aurorastanthony.org/',langs:['English'],urg:false,d:['rondo','frog']},
  rondo_clt:{name:'Rondo Community Land Trust',tagline:'Affordable homeownership and commercial space in the Rondo community. If you want to own your home, call them.',tagline_es:'Propiedad de vivienda asequible y espacio comercial en la comunidad de Rondo. Si quiere ser propietario de su propia casa en Saint Paul, llámeles.',tagline_so:'Lahaanshaha guri jaban iyo goobta ganacsiga ee bulshada Rondo. Haddaad rabto inaad guri lahaatid Saint Paul, wax ugu yeedh.',tagline_hmn:'Kev muaj tsev nyob thiab chaw lag luam muaj nqi pheej yig hauv zej zog Rondo. Yog tias koj xav muaj koj lub tsev hauv Saint Paul, hu lawv.',phone:'651-221-9884',addr:'1041 Selby Ave, St. Paul 55104',hrs:'Monday through Friday, business hours',url:'https://rondoclt.org/',langs:['English'],urg:false,d:['rondo']},
  keystone:{name:'Keystone Community Food Center',tagline:'No appointment needed. Walk in during service hours. You choose what you need. Serves downtown, North End, and Midway.',tagline_es:'Sin cita previa. Entre directamente durante el horario de servicio. Usted elige lo que necesita. Sirve al centro, North End y Midway de Saint Paul.',tagline_so:'Ballan looma baahna. Geli si toos ah inta lagu jiro saacadaha adeegga. Adiga oo dooraneyso waxa aad u baahan tahay. Downtownka, North End iyo Midway u adeegaysa.',tagline_hmn:'Tsis tas teem caij. Mus nkag ncaj qha thaum lub sij hawm pab. Koj xaiv yam koj xav tau. Ua rau downtown, North End thiab Midway Saint Paul.',phone:'651-917-3792',addr:'1800 University Ave W, St. Paul 55104 (corner of Fairview and University)',hrs:'Mon/Tue/Thu/Fri 10am-12pm and 2-4pm; Wed 4-7pm',url:'https://keystoneservices.org/food-shelf/',langs:['English'],urg:false,d:['north','midway','down']},
  mncn:{name:'Minnesota Community Care - North End',tagline:'Health care for everyone on the North End. Sliding scale pricing. No one turned away.',tagline_es:'Atención médica para todos en el North End de Saint Paul. Precio según ingresos. Nadie es rechazado.',tagline_so:'Daryeel caafimaad oo loogu talagalay dhammaan dadka North End Saint Paul. Qiimaha waxaa lagu xisaabiyaa dakhliga. Cidna looma diidin.',tagline_hmn:'Kev kho mob rau txhua tus ntawm North End Saint Paul. Nqi raws li nyiaj tau los. Tsis muaj leej twg raug tsis lees txais.',phone:'651-487-8539',addr:'740 W Rose Ave, St. Paul 55117',hrs:'Monday through Friday, 8am-4pm',url:'https://www.mncare.org/',langs:['English'],urg:false,d:['north']},
  shobi:{name:"Shobi's Table - Free Lunch Food Truck",tagline:'Free lunch from a food truck, Tuesday through Friday. Different location each day. No ID, no appointment, no questions.',tagline_es:'Almuerzo gratuito desde un camión de comida, martes a viernes. Ubicación diferente cada día. Sin identificación, sin cita, sin preguntas.',tagline_so:'Qado bilaash ah ee gaariga cuntada, Talaado ilaa Jimce. Goob kala duwan maalin kasta. Aqoonsiyo, ballan ama su\'aal looma baahna.',tagline_hmn:'Zaub mov tav su dawb los ntawm tsheb muab zaub mov, hnub Tuesday txog Friday. Qhov chaw sib txawv txhua hnub. Tsis tas muaj ntawv pov thawj, teem caij, lossis lus nug.',phone:null,addr:'Tue: 105 University Ave W | Wed: 1657 Rice St | Thu: 499 Charles Ave | Fri: 400 Snelling Ave N',hrs:'Tuesday through Friday, 12pm-1pm (closed January)',url:'https://www.shobistable.org/',langs:['English'],urg:false,d:['north','frog','midway','down']},
  opp:{name:'Saint Paul Opportunity Center - Full Services',tagline:'Free meals 3 times daily, showers, health care, mental health, housing help, and job training. Open 7 days a week.',tagline_es:'Comidas gratuitas tres veces al día, duchas, atención médica, salud mental, ayuda de vivienda y capacitación laboral. Abierto 7 días a la semana sin importar su situación.',tagline_so:'Cuntada bilaashka ah saddex jeer maalintii, musqusha, daryeelka caafimaadka, caafimaadka maskaxda, gargaarka guriga iyo tababarka shaqada. Furan 7 maalin toddobaadka.',tagline_hmn:'Zaub mov dawb peb zaug ib hnub, dej ntxuav cev, kev kho mob, kev pab kev xav, kev pab tsev nyob thiab kev kawm txuj ci hauj lwm. Qhib 7 hnub ib lim tiam.',phone:'651-228-0018',addr:'422 Dorothy Day Place, St. Paul 55102',hrs:'7 days a week. Breakfast 9-9:45am, Lunch 11:45am-12:45pm, Dinner 4:30-5:15pm',url:null,langs:['English'],urg:true,d:['down','midway']},
  cc_shlt:{name:'Catholic Charities - Emergency Shelter',tagline:'Emergency shelter for adults experiencing homelessness. Call first to get placed.',tagline_es:'Refugio de emergencia para adultos sin hogar. Llame primero para obtener una referencia.',tagline_so:'Magangal xaalada degdegga ah oo loogu talagalay dadka waaweyn ee aanay lahayn guri. Marka hore wac.',tagline_hmn:'Chaw pw xwm txheej ceev rau cov neeg laus tsis muaj tsev. Hu ua ntej.',phone:'651-266-1050',addr:'435 Dorothy Day Place, St. Paul 55102. Walk-in intake at St. Paul Opportunity Center, 422 Dorothy Day Place.',hrs:'Open every day - call first for referral',url:'https://cctwincities.org/services-and-locations/adult-emergency-shelters/higher-ground-saint-paul-shelter/',langs:['English'],urg:true,d:['down']},
  nbhh_high:{name:'Neighborhood House - Highland Food Shelf',tagline:'Food shelf in Highland Park at Sibley Manor Apartments. Call for hours and what to bring.',tagline_es:'Despensa de alimentos en Highland Park en los Apartamentos Sibley Manor. Llame para el horario actual y qué traer.',tagline_so:'Raafadda cuntada ee Highland Park ee Sibley Manor Apartments. Wac saacadaha iyo waxa la keeno.',tagline_hmn:'Chaw muab khoom noj hauv Highland Park ntawm Sibley Manor Apartments. Hu rau cov sijhawm thiab yam yuav tsum coj.',phone:'651-789-3630',addr:'Sibley Manor Apartments, Highland Park, St. Paul',hrs:'Call for current hours',url:'https://neighborhoodhousemn.org/programs/food-support/',langs:['English'],urg:false,d:['high']},
  joseph_coat:{name:"Joseph's Coat - Free Clothing",tagline:'Free clothing, household items, and personal hygiene items. Appointment required. West 7th Street location.',tagline_es:'Ropa gratuita, artículos para el hogar y productos de higiene personal. Se requiere cita. Ubicación en West 7th Street, Saint Paul.',tagline_so:'Dhar bilaash ah, waxyaabaha guriga iyo alaabada nadaafada shakhsiga. Ballan waa loo baahan yahay. Goobta West 7th Street, Saint Paul.',tagline_hmn:'Ris tsho dawb, cov khoom hauv tsev thiab cov khoom siv kev ntxuav. Teem caij xav tau. Qhov chaw West 7th Street, Saint Paul.',phone:'651-291-2472',addr:'1107 West 7th St, St. Paul 55102',hrs:'Mon & Wed 9am-3pm, by appointment only',url:'https://www.josephscoatmn.org/',langs:['English'],urg:false,d:['high','west','down']},
  united_fam:{name:'United Family Medicine',tagline:'Community health clinic on West 7th Street. Sliding scale fees. Primary care for everyone.',tagline_es:'Clínica de salud comunitaria en West 7th Street. Precio según ingresos. Atención primaria para todos los residentes de Saint Paul.',tagline_so:'Rugta caafimaadka bulshada ee West 7th Street. Qiimaha waxaa lagu xisaabiyaa dakhliga. Daryeelka asaasiga ah oo loogu talagalay dadka oo dhan.',tagline_hmn:'Chaw kho mob hauv zej zog ntawm West 7th Street. Nqi raws li nyiaj tau los. Kev kho mob pib rau txhua tus neeg nyob Saint Paul.',phone:'651-758-9500',addr:'1026 West 7th St, St. Paul 55102',hrs:'Monday through Friday, business hours',url:'https://www.ufmclinic.org/',langs:['English','Spanish'],urg:false,d:['high','west']},
  careerforce:{name:'CareerForce Saint Paul - Free Job Help',tagline:'Free job search help, resume writing, interview prep, and career training for everyone. Veterans services available. No cost for any services.',tagline_es:'Ayuda gratuita para búsqueda de empleo, currículos, preparación para entrevistas y capacitación profesional. Servicios para veteranos disponibles. Sin costo para ningún servicio.',tagline_so:'Gargaar bilaash ah oo ku saabsan raadinta shaqada, seeraha, diyaarinta wareysiga iyo tababarka xirfadda. Adeegyada askarta ayaa diyaar ah. Lacag looma bixiyo.',tagline_hmn:'Kev pab dawb nrhiav hauj lwm, sau ntawv thov hauj lwm, npaj rau kev xam phaj thiab kev kawm txuj ci hauj lwm. Kev pab cov tub rog muaj. Tsis them nqi.',phone:'651-266-9890',addr:'121 7th Place East, Suite 2300, St. Paul 55101 (Ramsey County Govt Center, 2nd floor)',hrs:'Monday through Friday, 8am-4:30pm',url:'https://careerforce.mn.gov/saintpaul',langs:['English'],urg:false,d:['all']},
  ujamaa:{name:'Ujamaa Place',tagline:'Free housing, jobs, education, and mental health support for Black men ages 18 to 30. Info sessions every Wednesday at 10am. All services free.',tagline_es:'Vivienda, empleos, educación y apoyo de salud mental gratuitos para hombres negros de 18 a 30 años en Saint Paul. Sesiones informativas cada miércoles a las 10am. Todos los servicios son completamente gratuitos.',tagline_so:'Guri, shaqo, waxbarasho iyo taageero caafimaad maskax bilaash ah oo loogu talagalay ragga madow ee 18-30 jirka Saint Paul. Xafladaha macluumaadka Arbacada kasta 10am.',tagline_hmn:'Tsev nyob, hauj lwm, kev kawm ntawv thiab kev pab kev xav dawb rau cov txiv neej dub hnub nyoog 18-30 xyoos hauv Saint Paul. Kev sib tham txhua hnub Wednesday 10am.',phone:'651-528-8006',addr:'University Ave, St. Paul (call for exact location)',hrs:'Info sessions: Wednesdays 10am. Call for full schedule.',url:'https://ujamaaplace.org/',langs:['English'],urg:false,d:['all','rondo','frog','midway']},
  shh_care:{name:'Second Harvest Heartland - Find Food Near You',tagline:'Call or text to find the nearest free food shelf or food distribution to you. Available in English, Spanish, Hmong, and Somali.',tagline_es:'Llame o envíe un mensaje de texto para encontrar la despensa de alimentos gratuita más cercana en las Ciudades Gemelas. Disponible en inglés, español, hmong y somalí.',tagline_so:'Wac ama farriinta qoraalka si aad u hesho raafadda cuntada bilaashka ah ee ugu dhow Twin Cities. Ingiriisi, Isbaanish, Hmong iyo Soomaali.',tagline_hmn:'Hu lossis xa SMS nrhiav chaw muab khoom noj dawb ze tshaj hauv Twin Cities. Muaj hauv lus Askiv, Spanish, Hmoob, thiab Somali.',phone:'866-844-3663',addr:'Call or text from anywhere in the Twin Cities',hrs:'Monday through Friday, 8am-4:30pm',url:'https://www.2harvest.org/',langs:['English','Spanish','Hmong','Somali'],urg:false,d:['all']},
  listening:{name:'Listening House - Drop-In Day Shelter',tagline:'No ID required. Walk in any time for a hot meal, coffee, clothing, phone access, showers, lockers, and someone who will listen.',tagline_es:'No se requiere identificación. Entre en cualquier momento para una comida caliente, café, ropa, acceso a teléfono, duchas, casilleros y alguien que le escuche. Sin preguntas.',tagline_so:'Aqoonsiyo looma baahna. Geli waqti kasta cunto kulul, qaxwe, dhar, gelitaanka telefoonka, musqusha, qafisha iyo qof dhegeysta. Su\'aal looma weydiin.',tagline_hmn:'Tsis tas muaj ntawv pov thawj. Mus nkag txhua lub sij hawm rau zaub mov kub, kas fes, ris tsho, siv xov tooj, dej ntxuav cev, lub thawv khaws khoom thiab muaj neeg mloog.',phone:'651-227-5911',addr:'421 E 7th St, St. Paul 55101',hrs:'Tuesday through Sunday, daytime hours - call ahead',url:'https://www.listeninghouse.org/',langs:['English'],urg:true,d:['down','east']},
  nbhh_mont:{name:'Neighborhood House - Montreal Ave Food Market',tagline:'Walk-in food market, no appointment needed. Open to everyone. No ID required. West Side and Highland area.',tagline_es:'Mercado de alimentos de entrada directa, sin cita previa. Abierto a todos. No se requiere identificación. Área del West Side e Highland de Saint Paul.',tagline_so:'Suuqa cuntada ee la geli karo si toos ah, ballan looma baahna. Furan dadka oo dhan. Aqoonsiyo looma baahna. Aagga West Side iyo Highland Saint Paul.',tagline_hmn:'Khw khoom noj mus nkag ncaj qha, tsis tas teem caij. Qhib rau txhua tus. Tsis tas muaj ntawv pov thawj. Cheeb tsam West Side thiab Highland Saint Paul.',phone:'651-789-3630',addr:'1080 Montreal Ave, St. Paul 55116',hrs:'Monday through Friday, 9am-11:30am and 1-4pm. Walk-in, no appointment.',url:'https://neighborhoodhousemn.org/programs/food-support/',langs:['English','Spanish','Hmong','Somali'],urg:false,d:['high','west']},
  macv:{name:'MACV - Veterans Housing and Legal Help',tagline:'Free housing, employment, and legal aid for veterans who are homeless or at risk. Vetlaw offers free legal help for any veteran on housing or employment.',tagline_es:'Vivienda gratuita, empleo y ayuda legal para veteranos sin hogar o en riesgo. El programa Vetlaw ofrece ayuda legal gratuita para cualquier veterano en temas de vivienda o empleo.',tagline_so:'Guri, shaqo iyo gargaar sharci bilaash ah oo loogu talagalay askarta aan lahayn guri ama halis ku jirta. Vetlaw waxay bixisaa gargaar sharci bilaash ah oo loogu talagalay dhammaan askarta.',tagline_hmn:'Tsev nyob, hauj lwm thiab kev pab lij choj dawb rau cov tub rog tsis muaj tsev lossis muaj kev pheej hmoo. Vetlaw muaj kev pab lij choj dawb rau txhua tus tub rog.',phone:'1-833-222-6228',addr:'1000 University Ave W, St. Paul 55104',hrs:'Call 24 hours a day, 7 days a week',url:'https://www.mac-v.org/',langs:['English'],urg:true,d:['all']},
  va_reg:{name:'VA Regional Office - Veterans Benefits',tagline:'Disability compensation, education, pensions, home loans, and all VA benefits counseling. Free for all veterans and their families.',tagline_es:'Compensación por discapacidad, educación, pensiones, préstamos para vivienda y asesoría sobre todos los beneficios del VA. Gratuito para todos los veteranos y sus familias.',tagline_so:'Magdhawga naafada, waxbarashada, barnaamijyada, amaahda guriga iyo talo ku saabsan dhammaan faa\'iidooyinka VA. Bilaash oo loogu talagalay dhammaan askarta iyo qoysaskooda.',tagline_hmn:'Kev them nqi rau kev xiam oob khab, kev kawm ntawv, nyiaj pension, tsev qiv nyiaj thiab kev qhia txog txhua cov txiaj ntsig VA. Dawb rau txhua tus tub rog thiab lawv tsev neeg.',phone:'1-800-827-1000',addr:'1 Federal Drive, Fort Snelling, St. Paul 55111',hrs:'Monday through Friday, 8am-4:30pm',url:'https://www.va.gov/st-paul-va-regional-benefit-office/',langs:['English'],urg:false,d:['all']},
  hope_dental:{name:'Hope Dental Clinic - Free Dental Care',tagline:'100% free dental care for low-income uninsured adults and children. Exams, cleanings, fillings, extractions. By appointment only.',tagline_es:'Atención dental 100% gratuita para adultos y niños sin seguro de bajos ingresos. Exámenes, limpiezas, empastes y extracciones. Solo con cita previa.',tagline_so:'Daryeel ilkaha 100% bilaash ah oo loogu talagalay dadka waaweyn iyo carruurta aan caymis lahayn ee dakhliga hoose. Baadhistaynta, nadiifinta, buuxinta, saarista.',tagline_hmn:'Kev kho hniav 100% dawb rau cov neeg laus thiab menyuam tsis muaj kev pov hwm muaj nyiaj tau los qis. Xyuas, ntxuav, sau, rho. Teem caij xwb.',phone:'651-789-7605',addr:'800 Minnehaha Ave E, St. Paul 55106',hrs:'Appointments Mon-Thu 8am-9pm. Calls Mon-Thu 8am-5pm.',url:'https://www.hopedentalclinic.org/',langs:['English','Spanish'],urg:false,d:['east']},
  ochc_frog:{name:'Open Cities Health Center - Frogtown',tagline:'Medical, dental, behavioral health, and eye care. Sliding scale. No one turned away. Interpreter in any language.',tagline_es:'Atención médica, dental, de salud conductual y ocular en Frogtown. Precio según ingresos. Nadie es rechazado. Intérprete disponible en cualquier idioma.',tagline_so:'Daryeelka caafimaadka, ilkaha, caafimaadka dabeecadda iyo indha Frogtown. Qiimaha waxaa lagu xisaabiyaa dakhliga. Cidna looma diidin. Turjumaan luuqad kasta.',tagline_hmn:'Kev kho mob, hniav, kev xav thiab lub qhov muag hauv Frogtown. Nqi raws li nyiaj tau los. Tsis muaj leej twg raug tsis lees txais. Muaj neeg txhais lus txhua hom lus.',phone:'651-290-9200',addr:'409 N Dunlap St, St. Paul 55104',hrs:'Mon/Wed-Fri 8am-5pm; Tue & Thu 8am-8pm; Sat 10am-2pm',url:'https://opencitieshealth.org/',langs:['English','Spanish','Hmong','Somali'],urg:false,d:['frog','midway']},
  ochc_north:{name:'Open Cities Health Center - North End',tagline:'Medical, dental, and behavioral health. Sliding scale. No one turned away. Interpreter in any language.',tagline_es:'Atención médica, dental y de salud conductual en el North End. Precio según ingresos. Nadie es rechazado. Intérprete disponible en cualquier idioma.',tagline_so:'Daryeelka caafimaadka, ilkaha iyo caafimaadka dabeecadda North End. Qiimaha waxaa lagu xisaabiyaa dakhliga. Cidna looma diidin. Turjumaan luuqad kasta.',tagline_hmn:'Kev kho mob, hniav thiab kev xav ntawm North End. Nqi raws li nyiaj tau los. Tsis muaj leej twg raug tsis lees txais. Muaj neeg txhais lus txhua hom lus.',phone:'651-290-9200',addr:'916 Rice St, St. Paul 55117',hrs:'Monday through Friday, 8am-5pm',url:'https://opencitieshealth.org/',langs:['English','Spanish','Hmong','Somali'],urg:false,d:['north']},
  smhc:{name:"St. Mary's Health Clinics - Free Medical",tagline:'Completely free primary care for low-income uninsured adults who do not qualify for other programs. Volunteer physicians. Multiple Saint Paul sites.',tagline_es:'Atención primaria completamente gratuita para adultos sin seguro de bajos ingresos que no califican para otros programas. Médicos voluntarios. Múltiples ubicaciones en Saint Paul.',tagline_so:'Daryeelka asaasiga ah ee buuxda oo bilaash ah oo loogu talagalay dadka waaweyn ee aan caymis lahayn ee dakhliga hoose ee aan u xaqiiqin barnaamijyada kale. Dhakhaatiirta u adeegsan.',tagline_hmn:'Kev kho mob pib tag nrho dawb rau cov neeg laus tsis muaj kev pov hwm muaj nyiaj tau los qis uas tsis tsim nyog rau lwm cov hauj lwm. Cov kws kho mob pab siab. Ntau qhov chaw hauv Saint Paul.',phone:'651-287-7777',addr:'Multiple Saint Paul locations - call for nearest site',hrs:'Clinics Mon-Thu afternoons. Call first.',url:'https://www.stmaryshealthclinics.org/',langs:['English','Spanish'],urg:false,d:['all']},
  comm_dental:{name:'Community Dental Care - Saint Paul',tagline:'Affordable dental care on a sliding scale. Medical Assistance accepted. East Side Saint Paul.',tagline_es:'Atención dental asequible con precio según ingresos en el East Side de Saint Paul. Medical Assistance aceptado.',tagline_so:'Daryeel ilkaha fudud oo lagu xisaabiyaa dakhliga ee East Side Saint Paul. Medical Assistance waa la aqbalaa.',tagline_hmn:'Kev kho hniav muaj nqi pheej yig raws li nyiaj tau los ntawm East Side Saint Paul. Medical Assistance txais.',phone:'651-778-1313',addr:'828 Hawthorne Ave E, St. Paul 55106',hrs:'Call for appointment hours',url:'https://www.communitydentalcare.org/',langs:['English','Spanish'],urg:false,d:['east']},
  mcc_dental_e:{name:'MN Community Care - East Side Dental',tagline:'Dental care on sliding scale fees. Medical Assistance accepted. Same location as the East Side health clinic.',tagline_es:'Atención dental con precio según ingresos en el East Side. Medical Assistance aceptado. Misma ubicación que la clínica de salud del East Side.',tagline_so:'Daryeel ilkaha oo lagu xisaabiyaa dakhliga East Side. Medical Assistance waa la aqbalaa. Isla goobta rugta caafimaadka East Side.',tagline_hmn:'Kev kho hniav raws li nyiaj tau los ntawm East Side. Medical Assistance txais. Tib qhov chaw li chaw kho mob East Side.',phone:'651-602-7500',addr:'895 E 7th St, St. Paul 55106',hrs:'Monday through Friday, 8am-5pm',url:'https://www.mncare.org/',langs:['English','Spanish','Somali','Hmong'],urg:false,d:['east']},
  mcc_dental_w:{name:'MN Community Care - West Side Dental',tagline:'Dental care on sliding scale fees. Medical Assistance accepted. Same location as the West Side health clinic.',tagline_es:'Atención dental con precio según ingresos en el West Side. Medical Assistance aceptado. Misma ubicación que la clínica de salud del West Side.',tagline_so:'Daryeel ilkaha oo lagu xisaabiyaa dakhliga West Side. Medical Assistance waa la aqbalaa. Isla goobta rugta caafimaadka West Side.',tagline_hmn:'Kev kho hniav raws li nyiaj tau los ntawm West Side. Medical Assistance txais. Tib qhov chaw li chaw kho mob West Side.',phone:'651-312-1996',addr:'478 S Robert St, St. Paul 55107',hrs:'Monday through Friday, 8am-4pm',url:'https://www.mncare.org/',langs:['English','Spanish'],urg:false,d:['west']},
  ese:{name:'East Side Elders',tagline:'Free help for seniors 65 and older on the East Side. Home repairs, chores, rides to appointments, and help signing up for other services. Since 2008.',tagline_es:'Ayuda gratuita para personas mayores de 65 años en el East Side. Reparaciones del hogar, quehaceres, transporte a citas médicas y ayuda para inscribirse en otros servicios. Desde 2008.',tagline_so:'Gargaar bilaash ah oo loogu talagalay waayeelka 65+ ee East Side. Dayactirka guriga, hawlaha guriga, raynta xafladaha iyo gargaarka diiwaan gelinta adeegyada kale.',tagline_hmn:'Kev pab dawb rau cov laus 65+ ntawm East Side. Kev kho vaj tsev, ua hauj lwm hauv tsev, caij tsheb mus kho mob thiab kev pab sau npe rau lwm cov kev pab.',phone:'651-683-2326',addr:'East Side, St. Paul',hrs:'Call for current hours',url:'https://eastsideelders.org/',langs:['English'],urg:false,d:['east']},
  ne_seniors:{name:'NE Seniors for Better Living',tagline:'Free home repairs for seniors 65 and older on the East Side. Senior lunch, memory cafe, and community activities every Thursday.',tagline_es:'Reparaciones gratuitas del hogar para personas mayores de 65 años en el East Side. Almuerzo para personas mayores, café de memoria y actividades comunitarias cada jueves.',tagline_so:'Dayactirka guriga bilaashka ah oo loogu talagalay waayeelka 65+ ee East Side. Qado waayeel, cafe xusuusnimada iyo xafladaha bulshada Khamiska kasta.',tagline_hmn:'Kev kho vaj tsev dawb rau cov laus 65+ ntawm East Side. Noj su rau cov laus, kev nco lus cafe thiab cov kev ua ub no rau zej zog txhua hnub Thursday.',phone:'651-808-1901',addr:'1831 Minnehaha Ave E, St. Paul 55119',hrs:'Thursdays 11am-2:30pm',url:'https://neseniorsforbetterliving.org/',langs:['English'],urg:false,d:['east']},
  meals_rc:{name:'Meals on Wheels - Ramsey County',tagline:'Free home-delivered meals for homebound seniors and adults with disabilities throughout Ramsey County. Call to enroll.',tagline_es:'Comidas gratuitas entregadas a domicilio para personas mayores y adultos con discapacidades en todo el Condado de Ramsey. Llame para inscribirse.',tagline_so:'Cuntada bilaashka ah oo guriga lagu keenaa waayeelka iyo dadka waaweyn ee naafada ah ee Degmada Ramsey oo dhan. Wac si aad ugu diwaangeliso.',tagline_hmn:'Zaub mov dawb xa mus rau tsev rau cov laus thiab cov neeg laus xiam oob khab thoob Ramsey County. Hu rau kev sau npe.',phone:'651-371-7009',addr:'Delivers throughout Ramsey County',hrs:'Call Monday through Friday',url:'https://www.mealsonwheels-rc.org/',langs:['English'],urg:false,d:['all']},
  help_door:{name:'Help at Your Door',tagline:'Grocery shopping, delivery, and errands for older adults and people with disabilities. Low cost sliding scale.',tagline_es:'Compras, entrega y mandados para adultos mayores y personas con discapacidades en Saint Paul. Precio bajo según ingresos.',tagline_so:'Xafiisyada badeecadaha, keenidda iyo hawlaha loogu talagalay dadka waaweyn iyo dadka naafada ah Saint Paul. Qiimaha hoose ee dakhliga ku salaysan.',tagline_hmn:'Yuav khoom, xa khoom thiab ua hauj lwm rau cov laus thiab cov neeg xiam oob khab hauv Saint Paul. Nqi qis raws li nyiaj tau los.',phone:'651-642-1892',addr:'Serves Saint Paul and surrounding areas',hrs:'Call for service schedule',url:'https://www.helpatyourdoor.org/',langs:['English'],urg:false,d:['all']},
  model_cities:{name:'Model Cities - Free Homeownership Counseling',tagline:'Free HUD-certified counseling to help first-time buyers, prevent foreclosure, and navigate renting. Focused on helping Black and BIPOC families build wealth.',tagline_es:'Asesoría gratuita certificada por HUD para compradores de vivienda por primera vez, prevención de ejecuciones hipotecarias y orientación de alquiler. Enfocada en ayudar a familias negras y BIPOC a construir riqueza.',tagline_so:'Talo bilaash ah oo HUD-ansixisay si loogu caawimo la-bixiyeyaasha ugu horreeyey, ka hortagga xukunta iyo hagaajinta kireyska. Diiradda waxaa lagu saaraa caawimada qoysaska madow iyo BIPOC.',tagline_hmn:'Kev qhia dawb tau txais HUD-pom zoo los pab cov neeg yuav tsev zaum xub thawj, tiv thaiv kev muab tsev rov rau tsev neeg, thiab kev coj mus rau kev xauj tsev. Tsom xam pab cov tsev neeg dub thiab BIPOC.',phone:'651-292-0131',addr:'839 University Ave W, St. Paul 55104',hrs:'Monday through Friday, business hours',url:'https://www.modelcities.org/',langs:['English'],urg:false,d:['all']},
  sp_dap:{name:'Saint Paul Down Payment Help - Up to $40,000',tagline:'Up to $40,000 toward buying your first home in Saint Paul. Income limits apply. Must complete free homebuyer counseling first.',tagline_es:'Hasta $40,000 para comprar su primera casa en Saint Paul. Se aplican límites de ingresos. Debe completar primero la orientación gratuita para compradores de vivienda.',tagline_so:'Ilaa $40,000 si aad u iibsato gurigaaga ugu horreeyey Saint Paul. Xaddidaadaha dakhliga ayaa dhacaya. Waa in la dhammaystiraa tababarka bixiyeyaasha guriga oo bilaash ah marka hore.',tagline_hmn:'Txog $40,000 rau kev yuav koj lub tsev thib ib hauv Saint Paul. Kev txwv nyiaj tau los siv. Yuav tsum ua tiav kev qhia dawb rau cov neeg yuav tsev ua ntej.',phone:'651-266-6655',addr:'Apply at stpaul.gov or call',hrs:'Monday through Friday, 8am-4:30pm',url:'https://www.stpaul.gov/departments/planning-and-economic-development/housing/citywide-downpayment-assistance-program',langs:['English'],urg:false,d:['all']},
  jeremiah:{name:'Jeremiah Program - Single Mothers',tagline:'Affordable housing, quality child care, college support, and life skills for single mothers working out of poverty. Rondo campus in Saint Paul.',tagline_es:'Vivienda asequible, cuidado infantil de calidad, apoyo universitario y habilidades para la vida para madres solteras trabajando para salir de la pobreza. Campus de Rondo en Saint Paul.',tagline_so:'Guri jaban, daryeel carruurnimada tayada sare leh, taageero jaamacadda iyo xirfadaha nolosha oo loogu talagalay hooyadaha keli ahaansha ah ee ka shaqeynaya saboolnimada.',tagline_hmn:'Tsev nyob muaj nqi pheej yig, kev tu menyuam zoo, kev pab kev kawm ntawv qib siab thiab cov txuj ci rau lub neej rau cov niam ib leeg uas ua hauj lwm tawm ntawm kev txom nyem.',phone:'651-332-5005',addr:'Rondo / Summit-University, St. Paul',hrs:'Call to apply or learn more',url:'https://jeremiahprogram.org/campuses/st-paul/',langs:['English'],urg:false,d:['rondo']},
  sanneh:{name:'Sanneh Foundation - Conway Community Center',tagline:'Youth programs, free meals, senior services, workforce training, and tech access. East Side community hub open 7 days a week.',tagline_es:'Programas juveniles, comidas gratuitas, servicios para personas mayores, capacitación laboral y acceso a tecnología. Centro comunitario del East Side abierto 7 días a la semana.',tagline_so:'Barnaamijyada da-yarta, cuntada bilaashka ah, adeegyada waayeelka, tababarka shaqada iyo gelitaanka teknoolojiyada. Xarunta bulshada ee East Side oo furan 7 maalin toddobaadka.',tagline_hmn:'Cov hauj lwm rau cov hluas, zaub mov dawb, kev pab cov laus, kev kawm txuj ci hauj lwm thiab kev siv thev naus laus zis. Lub hauv paus zej zog East Side qhib 7 hnub ib lim tiam.',phone:'651-690-4855',addr:'2090 Conway St, St. Paul 55119',hrs:'7 days a week - call for program schedule',url:'https://www.thesannehfoundation.org/',langs:['English','Somali'],urg:false,d:['east']},
  sppl_mh:{name:'Saint Paul Libraries - Free Mental Health Help',tagline:'A mental health professional is in Saint Paul Public Library branches. Free evaluations and referrals on the spot. No appointment or insurance needed.',tagline_es:'Un profesional de salud mental está en las sucursales de la Biblioteca Pública de Saint Paul. Evaluaciones y referencias gratuitas en el momento. Sin cita previa ni seguro.',tagline_so:'Xirfadlaha caafimaadka maskaxda ayaa ku jira laamaha Maktabadda Dadweynaha Saint Paul. Qiimeynta bilaashka ah iyo tixraacyada meel dhiggiisa ah. Ballan ama caymis looma baahna.',tagline_hmn:'Muaj kws txuj ci kev pab kev xav nyob hauv cov tsev qiv ntawv Saint Paul. Kev kwv yees dawb thiab kev xa mus lwm qhov ntawm lub chaw ntawd. Tsis tas teem caij lossis muaj kev pov hwm.',phone:'651-266-7000',addr:'Multiple Saint Paul Public Library locations',hrs:'Walk in during library open hours',url:'https://sppl.org/lmhp/',langs:['English'],urg:false,d:['all']},
  people_inc:{name:'People Incorporated - Mental Health',tagline:'Outpatient mental health services, housing support, and community care. Sliding scale fees. Serving Ramsey County.',tagline_es:'Servicios ambulatorios de salud mental, apoyo de vivienda y atención comunitaria. Precio según ingresos. Sirviendo al Condado de Ramsey.',tagline_so:'Adeegyada daryeelka caafimaadka maskaxda ee ambulatoriga ah, taageero guri iyo daryeel bulshada. Qiimaha waxaa lagu xisaabiyaa dakhliga. U adeegaya Degmada Ramsey.',tagline_hmn:'Kev pab kev xav tawm hauv tsev kho mob, kev pab tsev nyob thiab kev saib xyuas hauv zej zog. Nqi raws li nyiaj tau los. Ua rau Ramsey County.',phone:'651-774-0011',addr:'762 Transfer Rd Suite 21, St. Paul 55114',hrs:'Call for appointment availability',url:'https://peopleincorporated.org/',langs:['English'],urg:false,d:['all']},
  rs_eden:{name:'RS EDEN - Reentry Housing',tagline:'Two halfway houses in Saint Paul for adults leaving incarceration. Case management, mental health, and substance use support. Women with children welcome at Ashland site.',tagline_es:'Dos casas de transición en Saint Paul para adultos que salen de la cárcel. Manejo de casos, salud mental y apoyo para el uso de sustancias. Mujeres con niños bienvenidas en el sitio de Ashland.',tagline_so:'Laba guri oo dhexe ee Saint Paul oo loogu talagalay dadka waaweyn ee ka baxaya xabsiga. Maamulka kiiska, caafimaadka maskaxda iyo taageero ku tiirsanaanshaha.',tagline_hmn:'Ob lub tsev hauv Saint Paul rau cov neeg laus tawm hauv tsev loj cuj. Kev tswj kho, kev pab kev xav thiab kev pab kev haus dej haus cawv. Pojniam uas muaj menyuam txais tos.',phone:'612-782-2994',addr:'Twin Cities - call for intake. Housing intake: 612-782-2994. Main: 612-287-1600',hrs:'Call for intake information',url:'https://www.rseden.org/community-reentry-criminal-justice-support',langs:['English'],urg:false,d:['all']},
  rhsp:{name:'Returning Home Saint Paul',tagline:'City of Saint Paul program helping people recently released from incarceration find housing. Covers application fees, security deposits, and landlord guarantees. Contact through Ujamaa Place.',tagline_es:'Programa de la Ciudad de Saint Paul que ayuda a personas recién liberadas de la cárcel a encontrar vivienda. Cubre tarifas de solicitud, depósitos de seguridad y garantías de arrendador.',tagline_so:'Barnaamijka Magaalada Saint Paul ee caawimaya dadka dhow dhow ka soo daayay xabsiga si ay u helaan guri. Xafiisyada codsiga, deynta amaanahda iyo damaanadaha mulkiilaha.',tagline_hmn:'Hauj lwm ntawm Nroog Saint Paul pab cov neeg uas nyuam qhuav tawm hauv tsev loj cuj nrhiav tsev nyob. Them cov nqi thov, nyiaj ruaj khov thiab cov lav phib xub ntawm tus tswv tsev.',phone:'651-528-8006',addr:'Contact Ujamaa Place to apply',hrs:'Monday through Friday, business hours',url:'https://www.stpaul.gov/departments/financial-empowerment/returning-home-saint-paul',langs:['English'],urg:false,d:['all']},
  mh_reentry:{name:'Mitchell Hamline Reentry Clinic',tagline:'Free legal help for people with a criminal record. Law students supervised by attorneys handle expungement, family law, housing, and civil rights cases. Saint Paul.',tagline_es:'Ayuda legal gratuita para personas con antecedentes penales. Estudiantes de derecho supervisados por abogados manejan casos de borrado de antecedentes, derecho de familia, vivienda y derechos civiles.',tagline_so:'Gargaar sharci bilaash ah oo loogu talagalay dadka leh taariikhda dambiyada. Ardayda sharciga ayaa maamula arrimaha tirinta taariikhda, sharciga qoyska, guriga iyo xuquuqda madaniga.',tagline_hmn:'Kev pab lij choj dawb rau cov neeg muaj keeb kwm txhaum cai. Cov tub ntxhais kawm lij choj tswj los ntawm cov kws lij choj ua cov rooj plaub kev rho keeb kwm thiab cai tsev neeg.',phone:null,addr:'Mitchell Hamline School of Law, St. Paul',hrs:'Call or email to schedule intake',url:'https://mitchellhamline.edu/clinics/reentry-clinic/',langs:['English'],urg:false,d:['all']},
  smrls_exp:{name:'SMRLS - Free Expungement Clinic',tagline:'Free criminal record expungement help every 2-3 months. A volunteer attorney helps you prepare your petition. Income eligibility required. Call to schedule.',tagline_es:'Ayuda gratuita para borrar antecedentes penales cada 2-3 meses. Un abogado voluntario le ayuda a preparar su petición. Se requiere elegibilidad de ingresos. Llame con anticipación.',tagline_so:'Gargaar bilaash ah oo ku saabsan tirinta taariikhda dambiyada kasto 2-3 bilood. Qareen u adeegsan oo tiriyay ayaa kaa caawiya diyaarinta codsigaaga. Xaqiiqada dakhliga ayaa loo baahan yahay.',tagline_hmn:'Kev pab dawb kev rho keeb kwm txhaum cai txhua 2-3 lub hlis. Kws lij choj pab siab pub pab koj npaj koj ntawv thov. Kev tsim nyog nyiaj tau los xav tau.',phone:'1-877-696-6529',addr:'Multiple Saint Paul locations - call for next clinic date',hrs:'Clinics every 2-3 months - call ahead',url:'https://www.smrls.org/upcoming-clinics',langs:['English'],urg:false,d:['all']},
  ramsey_exp:{name:'Ramsey County Expungement Clinic',tagline:'Free walk-in help with criminal record expungement. Every 4th Thursday at 1pm at the Ramsey County Law Library. No appointment needed.',tagline_es:'Ayuda gratuita de entrada directa para borrar antecedentes penales. Cada cuarto jueves del mes a la 1pm en la Biblioteca Legal del Condado de Ramsey. Sin cita previa.',tagline_so:'Gargaar bilaash ah oo la geli karo si toos ah oo ku saabsan tirinta taariikhda dambiyada. Khamiskii afraad ee bil kasta 1pm Maktabadda Sharciga Degmada Ramsey.',tagline_hmn:'Kev pab dawb mus nkag ncaj qha rau kev rho keeb kwm txhaum cai. Txhua hnub Thursday thib plaub ntawm 1pm hauv Ramsey County Law Library.',phone:'651-266-8391',addr:'Ramsey County Law Library, 15 W Kellogg Blvd, St. Paul',hrs:'4th Thursday of each month, 1pm',url:'https://mncourts.libguides.com/expungement/legalhelp',langs:['English'],urg:false,d:['all']},
  helpseal:{name:'HelpSealMyRecord.org - Free Expungement',tagline:'Free service from the Minnesota Attorney General to seal older criminal records. Complete the form online. No attorney needed for qualifying cases.',tagline_es:'Servicio gratuito del Fiscal General de Minnesota para sellar antecedentes penales antiguos. Complete el formulario en línea. No se necesita abogado para casos que califican.',tagline_so:'Adeeg bilaash ah oo ka yimid Xoghayaha Guud ee Minnesota si loo xidhiidho diiwaanka dambiyada hore. Foomka online ku buuxi. Qareen looma baahna kiisaska la xaqiijiyay.',tagline_hmn:'Kev pab dawb los ntawm Minnesota Attorney General los kaw keeb kwm txhaum cai qub. Ua tiav daim foos hauv online. Tsis tas muaj kws lij choj rau cov rooj plaub tsim nyog.',phone:null,addr:'Online - HelpSealMyRecord.mn.gov',hrs:'Online 24 hours a day',url:'https://www.ag.state.mn.us/consumer/helpsealmyrecord.asp',langs:['English'],urg:false,d:['all']},
  emerge_mn:{name:'EMERGE Minnesota - Reentry Jobs',tagline:'Free job training, career coaching, transitional jobs, and housing resources for people with a criminal background. Twin Cities. Includes pre-release support from MN DOC facilities.',tagline_es:'Capacitación laboral gratuita, asesoría profesional, empleos de transición y recursos de vivienda para personas con antecedentes penales en las Ciudades Gemelas.',tagline_so:'Tababarka shaqada bilaashka ah, talaabada xirfadda, shaqooyinka kala guurka ah iyo kheyraadka guriga oo loogu talagalay dadka leh taariikhda dambiyada Twin Cities.',tagline_hmn:'Kev kawm txuj ci hauj lwm dawb, kev qhia txog txoj hauj lwm, cov hauj lwm kev hloov pauv thiab cov chaw pab tsev nyob rau cov neeg muaj keeb kwm txhaum cai hauv Twin Cities.',phone:'612-529-9267',addr:'Twin Cities locations - call for nearest',hrs:'Monday through Friday, business hours',url:'https://emerge-mn.org/reentry-services/',langs:['English'],urg:false,d:['all']},
  degrees180:{name:'180 Degrees - Justice Support',tagline:'Housing, mentoring, mental health, and life skills for people involved in the justice system. Serves youth and adults in Saint Paul and Minneapolis.',tagline_es:'Vivienda, mentoría, salud mental y habilidades para la vida para personas involucradas en el sistema de justicia. Sirve a jóvenes y adultos en Saint Paul y Minneapolis.',tagline_so:'Guri, mentoring, caafimaad maskax iyo xirfadaha nolosha oo loogu talagalay dadka ku lug leh nidaamka caddaaladda. U adeegaya da-yarta iyo dadka waaweyn ee Saint Paul iyo Minneapolis.',tagline_hmn:'Tsev nyob, kev qhia, kev pab kev xav thiab cov txuj ci rau lub neej rau cov neeg muaj feem nrog rau txoj kev ncaj ncees. Pab cov hluas thiab cov neeg laus hauv Saint Paul thiab Minneapolis.',phone:'612-822-1720',addr:'Saint Paul and Minneapolis locations',hrs:'Call for intake hours',url:'https://180degrees.org/',langs:['English'],urg:false,d:['all']},
  prep_prosper:{name:'Prepare + Prosper - Free Tax Help',tagline:'Free tax preparation for individuals earning under $40,000 or families under $70,000. IRS-certified volunteers. Federal, state, and property tax returns. By appointment.',tagline_es:'Preparación gratuita de impuestos para personas con ingresos menores de $40,000 o familias menores de $70,000. Voluntarios certificados por el IRS. Declaraciones federales, estatales y de impuestos a la propiedad.',tagline_so:'Diyaarinta canshuurta bilaashka ah oo loogu talagalay shakhsiyaadka ka yar $40,000 ama qoysaska ka yar $70,000. Saaxiibyada IRS-ansixisay. Diiwaannada federal, gobolka iyo canshuurta hantida.',tagline_hmn:'Kev npaj se dawb rau cov tib neeg tau nyiaj qis dua $40,000 lossis cov tsev neeg qis dua $70,000. Cov pab siab tau txais kev pom zoo los ntawm IRS. Cov ntawv se federal, xeev thiab vaj tsev.',phone:'651-287-0187',addr:'2610 University Ave W Suite 450, St. Paul 55114',hrs:'Tax season and summer clinics - call for schedule',url:'https://prepareandprosper.org/',langs:['English','Spanish'],urg:false,d:['all']},
  aarp_tax:{name:'AARP Tax-Aide - Free Tax Preparation',tagline:'Free tax preparation at Saint Paul Public Library branches. No age or income restriction. Volunteers are IRS-certified. No appointment needed at most sites.',tagline_es:'Preparación gratuita de impuestos en las sucursales de la Biblioteca Pública de Saint Paul. Sin restricción de edad ni ingresos. Voluntarios certificados por el IRS.',tagline_so:'Diyaarinta canshuurta bilaashka ah ee laamaha Maktabadda Dadweynaha Saint Paul. Xaddidaad da\'da ama dakhliga ma jirto. Saaxiibyada IRS-ansixisay.',tagline_hmn:'Kev npaj se dawb ntawm cov ceg Saint Paul Public Library. Tsis muaj kev txwv hnub nyoog lossis nyiaj tau los. Cov pab siab tau txais kev pom zoo los ntawm IRS.',phone:'888-227-7669',addr:'Multiple Saint Paul Public Library locations',hrs:'Tax season only - call for schedule',url:'https://www.aarp.org/money/taxes/aarp_taxaide/',langs:['English'],urg:false,d:['all']},
  juel_fair:{name:'Juel Fairbanks Recovery Services',tagline:'Substance use treatment in a culturally responsive, welcoming environment. Founded by a Native American. Focus on serving Native American men. Sliding scale.',tagline_es:'Tratamiento para el uso de sustancias en un ambiente culturalmente receptivo y acogedor. Fundado por una persona nativa americana. Precio según ingresos.',tagline_so:'Daaweynta adeegsiga waxyaabaha macquulka ah ee ka jawaabta dhaqanka, beeraha soo dhaweynta. Qiimaha waxaa lagu xisaabiyaa dakhliga.',tagline_hmn:'Kev kho mob kev haus dej haus cawv hauv ib lub vaj tsev sib txais tos thiab mloog pab rau txoj kab lis kev cai. Tsim nyem los ntawm ib tus neeg Native American. Nqi raws li nyiaj tau los.',phone:'651-645-3037',addr:'804 Albert St N, St. Paul 55104',hrs:'Call for intake information',url:'https://juelfairbanks.org/',langs:['English'],urg:false,d:['all']},
  mn_warmline:{name:'Minnesota Warmline - Peer Support',tagline:'Talk to someone who has been through mental health challenges themselves. Not a crisis line - for when you need to talk. Free, confidential, peer-to-peer.',tagline_es:'Hable con alguien que ha pasado por desafíos de salud mental. No es una línea de crisis, es para cuando necesita hablar. Gratuita, confidencial, entre compañeros.',tagline_so:'Kula hadal qof soo maray caqabadaha caafimaadka maskaxda. Khadka khataarta maahan - marka aad u baahan tahay inaad la hadasha. Bilaash, qarsoodi, isdhexgal.',tagline_hmn:'Tham nrog tus neeg uas tau dhau los ntawm cov teeb meem kev xav. Tsis yog kav xov tooj xwm txheej ceev - rau thaum koj xav tau tham nrog leej twg. Dawb, nkag siab, tib neeg rau tib neeg.',phone:'651-288-0400',addr:'Call from anywhere in Minnesota',hrs:'Daily 5pm-10pm. Sat-Sun also 9am-5pm',url:'https://mnwarmline.org/',langs:['English'],urg:false,d:['all']},
  centro:{name:'Centro - Latino Community Services',tagline:'Job training, legal help, financial coaching, and economic support for the Latino community. West Side and Frogtown. All are welcome.',tagline_es:'Capacitación laboral, ayuda legal, asesoría financiera y apoyo económico para la comunidad latina en el West Side y Frogtown de Saint Paul. Todos son bienvenidos.',tagline_so:'Tababarka shaqada, gargaarka sharciga, talaabada maaliyadda iyo taageero dhaqaale oo loogu talagalay bulshada Laatiiniga West Side iyo Frogtown Saint Paul.',tagline_hmn:'Kev kawm txuj ci hauj lwm, kev pab lij choj, kev qhia txog nyiaj thiab kev txhawb kev lag luam rau zej zog Latino ntawm West Side thiab Frogtown Saint Paul.',phone:'651-379-4605',addr:'420 Wabasha St S, St. Paul 55107',hrs:'Monday through Friday, business hours',url:'https://centromn.org/',langs:['English','Spanish'],urg:false,d:['west','frog']},
  njc:{name:'Neighborhood Justice Center - Criminal Defense',tagline:'Free criminal defense and expungement for people who cannot afford an attorney. Ramsey, Dakota, and Washington counties. Call for intake.',tagline_es:'Defensa penal y borrado de antecedentes gratuitos para personas que no pueden pagar un abogado. Condados de Ramsey, Dakota y Washington. Llame para admisión.',tagline_so:'Difaac dambiga iyo tirinta bilaashka ah oo loogu talagalay dadka aan awoodi karin qareen. Degmooyinka Ramsey, Dakota iyo Washington.',tagline_hmn:'Kev tiv thaiv hom txhaum cai thiab kev rho keeb kwm dawb rau cov neeg uas tsis muaj peev xwm them kws lij choj. Ramsey, Dakota, thiab Washington counties.',phone:'651-222-4703',addr:'Serves Ramsey, Dakota, and Washington counties',hrs:'Call for intake hours',url:'https://neighborhoodjustice.org/',langs:['English'],urg:true,d:['all']},
  mn_recovery:{name:'Minnesota Recovery Connection',tagline:'Peer-run support and connection to addiction treatment. Real people in recovery help you find the right program. Free, confidential.',tagline_es:'Apoyo entre compañeros y conexión a tratamiento para adicciones. Personas reales en recuperación le ayudan a encontrar el programa adecuado. Gratuito, confidencial.',tagline_so:'Taageero isdhexgal ah iyo xiriirka daaweynta ku tiirsanaanshaha. Dadka dhabta ahi oo si run ah ugu jirey waxay kaa caawiyaan si aad u hesho barnaamijka saxda ah.',tagline_hmn:'Kev txhawb tib neeg rau tib neeg thiab kev sib txuas rau kev kho mob kev haus dej haus cawv. Cov neeg tiag uas dhau los ntawm kev rov zoo pab koj nrhiav txoj hauj lwm tsim nyog.',phone:'651-238-2999',addr:'Call or visit online',hrs:'Monday through Friday, business hours',url:'https://mnrecovery.org/',langs:['English'],urg:false,d:['all']},
  snap_ramsey:{name:'Ramsey County SNAP Food Benefits',tagline:'Apply for monthly food benefits (food stamps) through Ramsey County. If you qualify, benefits load onto an EBT card you can use at most grocery stores.',tagline_es:'Solicite beneficios mensuales de alimentos a través del Condado de Ramsey. Los beneficios se cargan en una tarjeta EBT que puede usar en la mayoría de las tiendas de comestibles.',tagline_so:'Codsiga faa\'iidooyinka cuntada bishii iyada oo loo marayo Degmada Ramsey. Faa\'iidooyinku waxay ku raraan kaarka EBT si loogu isticmaalo dukaamada badankooda.',tagline_hmn:'Thov cov txiaj ntsig khoom noj txhua hli los ntawm Ramsey County. Cov txiaj ntsig muab rau ntawm daim EBT card uas siv tau hauv feem ntau cov khw muag khoom noj.',phone:'651-266-4444',addr:'Apply online at mnbenefits.mn.gov or by phone',hrs:'Monday through Friday, 8am-4:30pm',url:'https://www.ramseycounty.us/residents/health-medical/health-programs/food-support',langs:['English','Spanish','Somali','Hmong'],urg:false,d:['all']},

  /* ── STATEWIDE REENTRY ─────────────────────────────────────────────── */

  mn_doc:{name:'MN Dept of Corrections - Reentry Services',tagline:'The official Minnesota state reentry program. Whether you are still inside or recently released, this is your first call for supervision requirements, housing referrals, employment connections, and transition planning. Statewide.',tagline_es:'El programa oficial de reinserción del estado de Minnesota. Si todavía está dentro o fue liberado recientemente, este es su primer llamado para requisitos de supervisión, referencias de vivienda y planificación de transición.',tagline_so:'Barnaamijka rasmiga ah ee dib u bilaabista gobolka Minnesota. Haddaad gudaha jirto ama dhow dhow lagaa soo daayay, tani waa wacashada ugu horreysa ee shuruudaha kormeerka iyo tixraacyada guriga.',tagline_hmn:'Txoj hauj lwm rasmim kev rov qab rau hauv Minnesota. Tsis hais tias koj tseem nyob sab hauv lossis nyuam qhuav tawm, no yog koj thawj lub hu xov tooj rau kev npaj kev hloov.',phone:'651-361-7200',addr:'1450 Energy Park Dr, St. Paul 55108. Supervision offices in every county.',hrs:'Monday through Friday, business hours',url:'https://mn.gov/doc/community-supervision/reentry-services/',langs:['English'],urg:false,d:['all']},

  careerforce_mn:{name:'CareerForce - Free Job Help Statewide',tagline:'Free job search, resume help, interview prep, and career training at 50+ locations across Minnesota. Locations in Duluth, Brainerd, St. Cloud, Mankato, Rochester, and the Twin Cities. No cost for any services.',tagline_es:'Búsqueda de empleo gratuita, ayuda con currículos, preparación para entrevistas y capacitación profesional en más de 50 ubicaciones en Minnesota, incluyendo Duluth, Brainerd, Mankato y Rochester.',tagline_so:'Raadinta shaqada bilaashka ah, gargaarka seeraha, diyaarinta wareysiga iyo tababarka xirfadda ee 50+ goobood oo Minnesota ka mid ah, oo ay ku jiraan Duluth, Brainerd, Mankato iyo Rochester.',tagline_hmn:'Kev nrhiav hauj lwm dawb, kev pab ntawv thov hauj lwm, kev npaj rau kev xam phaj thiab kev kawm txuj ci hauj lwm ntawm 50+ qhov chaw thoob Minnesota suav nrog Duluth, Brainerd, Mankato, Rochester.',phone:'651-259-7500',addr:'Find your nearest location at careerforce.mn.gov',hrs:'Monday through Friday, business hours. Hours vary by location.',url:'https://careerforce.mn.gov/',langs:['English','Spanish','Hmong','Somali'],urg:false,d:['all']},

  cmnrp:{name:'Central MN Reentry Project - St. Cloud Area',tagline:'Free reentry services for people with a felony in Stearns, Benton, or Sherburne counties within 365 days of release. Housing, employment, education, clothing, and family services. Covers Brainerd and Moose Lake corridors. By appointment.',tagline_es:'Servicios gratuitos de reinserción para personas con un delito grave en los condados de Stearns, Benton o Sherburne dentro de los 365 días posteriores a la liberación. Vivienda, empleo, educación, ropa y servicios familiares. Cubre el corredor de Brainerd y Moose Lake.',tagline_so:'Adeegyada dib u bilaabista bilaashka ah oo loogu talagalay dadka leh dambiyada cidanka ah ee degmooyinka Stearns, Benton ama Sherburne 365 maalmood ka dib marka laga saaro. Guri, shaqo, waxbarasho.',tagline_hmn:'Cov kev pab rov qab dawb rau cov neeg muaj rooj plaub txhaum cai hauv Stearns, Benton, lossis Sherburne counties hauv 365 hnub tom qab tso tawm. Tsev nyob, hauj lwm, kev kawm ntawv, ris tsho.',phone:'320-310-1797',addr:'PO Box 2391, St. Cloud MN 56302',hrs:'Tue, Wed, Thu 10am-4pm by appointment',url:'https://cmnrp.org/',langs:['English'],urg:false,d:['all']},

  lss_reentry:{name:'Lutheran Social Service - Transitional Housing Statewide',tagline:'Transitional housing and reentry support across Minnesota including Duluth, Brainerd, Mankato, Rochester, Willmar, and Twin Cities. Portland House for men in Minneapolis. Call main number or visit online to find your nearest location.',tagline_es:'Vivienda de transición y apoyo de reinserción en todo Minnesota, incluyendo Duluth, Brainerd, Mankato, Rochester, Willmar y las Ciudades Gemelas. Llame para encontrar su ubicación más cercana.',tagline_so:'Guri kala guurka ah iyo taageero dib u bilaabista oo ku firirsan Minnesota oo dhan, oo ay ku jiraan Duluth, Brainerd, Mankato, Rochester, Willmar iyo Twin Cities.',tagline_hmn:'Tsev nyob kev hloov pauv thiab kev txhawb rov qab thoob Minnesota suav nrog Duluth, Brainerd, Mankato, Rochester, Willmar thiab Twin Cities.',phone:'651-642-5990',addr:'Statewide - call for your nearest location',hrs:'Monday through Friday, business hours',url:'https://www.lssmn.org/',langs:['English','Spanish','Somali'],urg:false,d:['all']},

  /* ── SEXUAL VIOLENCE / SUPPORT ───────────────────────────────────── */

  day1:{name:'Day One - Sexual Violence & DV Crisis Line',tagline:'Free, confidential 24-hour crisis line for survivors of sexual violence, domestic violence, and trafficking anywhere in Minnesota. Talk to a trained advocate by phone, text, or chat. No police involvement required. You are in control.',tagline_es:'Línea de crisis gratuita, confidencial y disponible las 24 horas para sobrevivientes de violencia sexual, violencia doméstica y tráfico en cualquier lugar de Minnesota. Sin participación policial requerida. Usted está en control.',tagline_so:'Khadka xaalada degdegga ah oo bilaash ah, qarsoodi ah iyo 24-saacadood oo loogu talagalay kuwii silaadda galmoodka, rabshadda guriga iyo ganacsiga aadanaha ka badbaadey meel kasta Minnesota. Booliska lama baahna.',tagline_hmn:'Kav xov tooj xwm txheej ceev dawb, nkag siab thiab 24 teev rau cov neeg dim ntawm kev tsim txom poj niam txiv neej, kev tsim txom hauv tsev, thiab kev muag neeg. Tsis tas muaj kev koom tes ntawm tub ceev xwm.',phone:'1-866-223-1111',addr:'Call or text 612-399-9995. Available statewide.',hrs:'24 hours a day, 7 days a week',url:'https://dayoneservices.org/',langs:['English','Spanish','Somali','Hmong'],urg:true,d:['all']},

  sos_sa:{name:'SOS Sexual Violence Services - Ramsey County',tagline:'Free, confidential support for survivors of sexual violence in Ramsey County. 24-hour crisis line, medical advocacy at Regions and St. Johns hospitals, legal advocacy, counseling, and support groups. You do not have to report to police to get help or a medical exam.',tagline_es:'Apoyo gratuito y confidencial para sobrevivientes de violencia sexual en el Condado de Ramsey. Línea de crisis 24 horas, defensa médica hospitalaria, defensa legal, consejería y grupos de apoyo. No tiene que reportar a la policía para recibir ayuda.',tagline_so:'Taageero bilaash ah, qarsoodi ah oo loogu talagalay kuwii silaadda galmoodka ka badbaadey ee Degmada Ramsey. Khadka xaalada degdegga 24-saacadood, difaaca caafimaadka, difaaca sharciga. Booliska ma baahna.',tagline_hmn:'Kev pab dawb, nkag siab rau cov neeg dim ntawm kev tsim txom poj niam txiv neej hauv Ramsey County. Kav xov tooj 24 teev, kev tiv thaiv kev kho mob, kev tiv thaiv lij choj. Tsis tas qhia tub ceev xwm.',phone:'651-266-1000',addr:'Saint Paul - call for services. SANE exams at Regions, St. Johns, and United Hospitals.',hrs:'24 hours a day, 7 days a week',url:'https://www.ramseycounty.us/residents/health-medical/clinics-services/sos-sexual-violence-services',langs:['English','Spanish','Somali','Hmong'],urg:true,d:['all']},

  standpoint:{name:'Standpoint - Legal Advocacy for Survivors',tagline:'Free statewide legal advocacy for survivors of sexual violence and domestic violence. Lawyers and advocates help you understand your options. Serves all survivors regardless of immigration status, nationality, religion, or any other background.',tagline_es:'Defensa legal gratuita en todo el estado para sobrevivientes de violencia sexual y violencia doméstica. Abogados y defensores le ayudan a entender sus opciones. Sirve a todos los sobrevivientes sin importar su estatus migratorio.',tagline_so:'Difaaca sharciga bilaashka ah ee gobolka oo dhan oo loogu talagalay kuwii silaadda galmoodka iyo rabshadda guriga ka badbaadey. Waxay u adeegaan dhammaan kuwii badbaaday si aan loo eegin xaaladda socdaalka.',tagline_hmn:'Kev tiv thaiv lij choj dawb thoob plaws lub xeev rau cov neeg dim ntawm kev tsim txom poj niam txiv neej thiab kev tsim txom hauv tsev. Pab txhua cov neeg dim tsis hais xwm txheej kev tsiv teb tsaws chaw.',phone:'1-800-313-2666',addr:'Call during business hours. For after-hours emergencies call Day One at 1-866-223-1111.',hrs:'Monday through Friday, business hours',url:'https://www.standpointmn.org/',langs:['English','Spanish'],urg:false,d:['all']},

  mncasa:{name:'MNCASA - Find a Sexual Violence Advocate Near You',tagline:'Minnesota Coalition Against Sexual Assault connects you to a free, confidential advocate in any county in Minnesota. Advocates are available 24/7 and can help whether something just happened or happened long ago.',tagline_es:'La Coalición de Minnesota Contra la Agresión Sexual le conecta con un defensor gratuito y confidencial en cualquier condado de Minnesota, disponible las 24 horas. Use el localizador en línea.',tagline_so:'Isbahaysiga Minnesota Xad-gudubka Galmoodka Xukumaaya waxay kugu xiraysaa difaac bilaash ah, qarsoodi ah oo ku sugan degmo kasta ee Minnesota. Difaacayaashu waxay diyaar yihiin 24 saacadood.',tagline_hmn:'Minnesota Coalition Against Sexual Assault txuas koj rau tus neeg tiv thaiv dawb, nkag siab hauv txhua lub county hauv Minnesota. Cov neeg tiv thaiv muaj 24 teev.',phone:null,addr:'Find your nearest advocate at mncasa.org/find-help',hrs:'Advocates available 24 hours. Use the online locator.',url:'https://mncasa.org/find-help/',langs:['English'],urg:false,d:['all']}
};
